  ('awes', 'army-public-school', '{"en":"AWES Army Public School (PRT/TGT/PGT)","hi":"AWES आर्मी पब्लिक स्कूल (PRT/TGT/PGT)"}'::jsonb, 'APS', '{"en":"Army Welfare Education Society","hi":"आर्मी वेलफेयर एजुकेशन सोसाइटी"}'::jsonb, 'national', null, '{"en":"Online screening test for 130+ Army Public Schools. Part A is teaching aptitude and reasoning; Part B is the subject.","hi":"130+ आर्मी पब्लिक स्कूलों हेतु ऑनलाइन स्क्रीनिंग परीक्षा। भाग A शिक्षण अभिरुचि एवं तर्कशक्ति तथा भाग B विषय आधारित।"}'::jsonb, '{"en":"Annual — usually November","hi":"वार्षिक — प्रायः नवंबर"}'::jsonb, '#166534', '🎖️', null, '[{"en":"B.Ed mandatory for all posts","hi":"सभी पदों हेतु B.Ed अनिवार्य"},{"en":"Age below 40 for fresh candidates","hi":"नए अभ्यर्थियों हेतु आयु 40 वर्ष से कम"}]'::jsonb, '[{"en":"Score card valid for lifetime","hi":"स्कोर कार्ड आजीवन मान्य"},{"en":"Negative marking of 0.25","hi":"0.25 ऋणात्मक अंकन"}]'::jsonb, 'https://awesindia.com', null),
  ('emrs', 'emrs', '{"en":"EMRS Teaching Staff (NESTS)","hi":"EMRS शिक्षण स्टाफ (NESTS)"}'::jsonb, 'EMRS', '{"en":"National Education Society for Tribal Students","hi":"राष्ट्रीय जनजातीय छात्र शिक्षा समिति"}'::jsonb, 'national', null, '{"en":"Recruitment to Eklavya Model Residential Schools for tribal students across India.","hi":"देशभर में जनजातीय छात्रों हेतु एकलव्य आदर्श आवासीय विद्यालयों में भर्ती।"}'::jsonb, '{"en":"As per NESTS notification","hi":"NESTS अधिसूचना के अनुसार"}'::jsonb, '#7C3AED', '🏞️', null, '[{"en":"TGT: Graduation + B.Ed + CTET Paper 2","hi":"TGT: स्नातक + B.Ed + CTET पेपर 2"},{"en":"PGT: Post Graduation + B.Ed","hi":"PGT: स्नातकोत्तर + B.Ed"}]'::jsonb, '[{"en":"Residential campus posting","hi":"आवासीय परिसर पदस्थापन"},{"en":"Central government pay scale","hi":"केंद्र सरकार वेतनमान"}]'::jsonb, 'https://emrs.tribal.gov.in', null)
insert into exam_updates (exam_id, date, kind, title, detail) values
  ('ctet', '2026-05-11'::date, 'notification', '{"en":"Notification released","hi":"अधिसूचना जारी"}'::jsonb, '{"en":"CBSE opened the CTET September 2026 cycle on ctet.nic.in.","hi":"CBSE ने ctet.nic.in पर CTET सितंबर 2026 चक्र आरंभ किया।"}'::jsonb),
  ('ctet', '2026-06-10'::date, 'application', '{"en":"Application window closed","hi":"आवेदन विंडो बंद"}'::jsonb, '{"en":"Applications ran from 11 May to 10 June 2026, with corrections 15-18 June.","hi":"आवेदन 11 मई से 10 जून 2026 तक चले, संशोधन 15-18 जून।"}'::jsonb),
  ('ctet', '2026-09-06'::date, 'exam', '{"en":"Exam day","hi":"परीक्षा दिवस"}'::jsonb, '{"en":"Paper II 9:30 AM-12:00 noon, Paper I 2:30-5:00 PM. Offline OMR across 132 cities.","hi":"पेपर II प्रातः 9:30-12:00, पेपर I दोपहर 2:30-5:00। 132 शहरों में ऑफ़लाइन OMR।"}'::jsonb),
  ('htet', '2025-12-24'::date, 'notification', '{"en":"Notification released","hi":"अधिसूचना जारी"}'::jsonb, '{"en":"BSEH Bhiwani opened the HTET cycle; about 2.45 lakh candidates registered.","hi":"BSEH भिवानी ने HTET चक्र आरंभ किया; लगभग 2.45 लाख अभ्यर्थी पंजीकृत।"}'::jsonb),
  ('htet', '2026-07-04'::date, 'exam', '{"en":"Level 3 (PGT) exam","hi":"स्तर 3 (PGT) परीक्षा"}'::jsonb, '{"en":"Held 3:00-5:30 PM on 4 July 2026.","hi":"4 जुलाई 2026 को अपराह्न 3:00-5:30 बजे आयोजित।"}'::jsonb),
  ('htet', '2026-07-05'::date, 'exam', '{"en":"Level 2 and Level 1 exams","hi":"स्तर 2 एवं स्तर 1 परीक्षा"}'::jsonb, '{"en":"Level 2 (TGT) 10:00 AM-12:30 PM and Level 1 (PRT) 3:00-5:30 PM on 5 July 2026.","hi":"5 जुलाई 2026 को स्तर 2 (TGT) प्रातः 10:00-12:30 तथा स्तर 1 (PRT) अपराह्न 3:00-5:30।"}'::jsonb),
  ('uptet', '2026-03-20'::date, 'notification', '{"en":"Notification released after four years","hi":"चार वर्ष बाद अधिसूचना जारी"}'::jsonb, '{"en":"UPESSC reopened UPTET on 20 March 2026; applications ran 27 March to 26 April.","hi":"UPESSC ने 20 मार्च 2026 को UPTET पुनः आरंभ किया; आवेदन 27 मार्च से 26 अप्रैल तक।"}'::jsonb),
  ('uptet', '2026-07-02'::date, 'exam', '{"en":"Exam held over three days","hi":"तीन दिन परीक्षा आयोजित"}'::jsonb, '{"en":"Conducted 2, 3 and 4 July 2026 in offline OMR mode, two shifts each day.","hi":"2, 3 एवं 4 जुलाई 2026 को ऑफ़लाइन OMR मोड में, प्रतिदिन दो पालियों में आयोजित।"}'::jsonb),
  ('uptet', '2026-07-08'::date, 'result', '{"en":"Response sheet released","hi":"उत्तर पत्रक जारी"}'::jsonb, '{"en":"Provisional response sheet out 8 July; objections accepted 8-14 July 2026.","hi":"अनंतिम उत्तर पत्रक 8 जुलाई को जारी; आपत्तियाँ 8-14 जुलाई 2026 तक।"}'::jsonb),
  ('bihartet', '2026-08-04'::date, 'vacancy', '{"en":"TRE 4.0 vacancies announced","hi":"TRE 4.0 रिक्तियाँ घोषित"}'::jsonb, '{"en":"32,388 teacher posts across Classes 1-12 — among the largest drives in Bihar.","hi":"कक्षा 1-12 हेतु 32,388 शिक्षक पद — बिहार के सबसे बड़े अभियानों में से एक।"}'::jsonb),
  ('bihartet', '2026-09-22'::date, 'exam', '{"en":"TRE 4.0 examination","hi":"TRE 4.0 परीक्षा"}'::jsonb, '{"en":"Scheduled 22-27 September 2026; results expected November 2026.","hi":"22-27 सितंबर 2026 को निर्धारित; परिणाम नवंबर 2026 अपेक्षित।"}'::jsonb),
  ('dsssb', '2026-04-12'::date, 'exam', '{"en":"PGT computer-based exam","hi":"PGT कंप्यूटर आधारित परीक्षा"}'::jsonb, '{"en":"PGT CBT ran 12-17 April 2026 for 510 posts across 33 categories, 300 marks.","hi":"510 पदों (33 श्रेणियाँ) हेतु PGT CBT 12-17 अप्रैल 2026, 300 अंक।"}'::jsonb),
  ('dsssb', '2026-06-16'::date, 'application', '{"en":"TGT applications opened","hi":"TGT आवेदन आरंभ"}'::jsonb, '{"en":"838 TGT vacancies; applications ran 16 June to 15 July 2026.","hi":"838 TGT रिक्तियाँ; आवेदन 16 जून से 15 जुलाई 2026 तक।"}'::jsonb),
  ('kvs', '2025-11-13'::date, 'notification', '{"en":"Notification released","hi":"अधिसूचना जारी"}'::jsonb, '{"en":"9,921 posts: 3,630 PRT, 3,069 TGT and 1,606 PGT.","hi":"9,921 पद: 3,630 PRT, 3,069 TGT तथा 1,606 PGT।"}'::jsonb),
  ('kvs', '2026-01-10'::date, 'exam', '{"en":"Tier 1 screening test","hi":"टियर 1 स्क्रीनिंग परीक्षा"}'::jsonb, '{"en":"Two-tier CBT introduced this cycle; Tier 1 held 10-11 January 2026 for 100 marks.","hi":"इस चक्र में दो-स्तरीय CBT लागू; टियर 1 100 अंकों हेतु 10-11 जनवरी 2026 को।"}'::jsonb),
  ('nvs', '2026-01-10'::date, 'exam', '{"en":"Computer-based test","hi":"कंप्यूटर आधारित परीक्षा"}'::jsonb, '{"en":"CBT held 10-11 January 2026 for 5,841 teaching and non-teaching posts.","hi":"5,841 शिक्षण एवं गैर-शिक्षण पदों हेतु CBT 10-11 जनवरी 2026 को आयोजित।"}'::jsonb),
  ('reet', '2026-01-17'::date, 'exam', '{"en":"REET held over four days","hi":"चार दिन REET आयोजित"}'::jsonb, '{"en":"Level 1 and Level 2 conducted 17-20 January 2026 by BSER Ajmer.","hi":"BSER अजमेर द्वारा स्तर 1 एवं स्तर 2 की परीक्षा 17-20 जनवरी 2026 को आयोजित।"}'::jsonb),
  ('reet', '2026-01-20'::date, 'vacancy', '{"en":"REET Mains vacancies announced","hi":"REET मुख्य परीक्षा रिक्तियाँ घोषित"}'::jsonb, '{"en":"The follow-on REET Mains recruitment carries 10,208 third-grade teacher posts.","hi":"आगामी REET मुख्य भर्ती में 10,208 तृतीय श्रेणी अध्यापक पद।"}'::jsonb),
  ('hssc-tgt-pgt', '2026-08-21'::date, 'application', '{"en":"TGT and PGT applications open","hi":"TGT एवं PGT आवेदन आरंभ"}'::jsonb, '{"en":"8,394 HSSC vacancies; apply 21 August to 21 September 2026. Fee Rs 500 general, Rs 125 reserved.","hi":"8,394 HSSC रिक्तियाँ; आवेदन 21 अगस्त से 21 सितंबर 2026। शुल्क सामान्य ₹500, आरक्षित ₹125।"}'::jsonb),
  ('hssc-tgt-pgt', '2026-08-21'::date, 'vacancy', '{"en":"State-wide teacher drive","hi":"राज्यव्यापी शिक्षक भर्ती"}'::jsonb, '{"en":"Haryana announced 15,659 PRT, TGT and PGT posts across HSSC, HPSC and HKRN.","hi":"हरियाणा ने HSSC, HPSC एवं HKRN के माध्यम से 15,659 PRT, TGT एवं PGT पद घोषित किए।"}'::jsonb);
