insert into educators (id, name, avatar, headline, bio, subjects, experience_years, languages) values
  ('edu-anjali', 'Anjali Verma', '👩‍🏫', '{"en":"CDP & Pedagogy — 9 years, 4L+ learners","hi":"CDP एवं शिक्षाशास्त्र — 9 वर्ष, 4 लाख+ शिक्षार्थी"}'::jsonb, '{"en":"M.Ed from Jamia Millia Islamia. Known for turning Piaget and Vygotsky into one-line memory hooks that survive exam pressure.","hi":"जामिया मिल्लिया इस्लामिया से M.Ed। पियाजे एवं वाइगोत्स्की को ऐसे एक-पंक्ति स्मृति सूत्रों में बदलने हेतु प्रसिद्ध जो परीक्षा के दबाव में भी याद रहते हैं।"}'::jsonb, array['cdp']::text[], 9, array['hi', 'en']::text[]),
  ('edu-rakesh', 'Rakesh Yadav', '👨‍🏫', '{"en":"Maths & Maths Pedagogy — 12 years","hi":"गणित एवं गणित शिक्षाशास्त्र — 12 वर्ष"}'::jsonb, '{"en":"Teaches Class 1-8 maths the way NCERT intends it — concept first, shortcut second. 12 years across CTET, UPTET and Super TET batches.","hi":"कक्षा 1-8 गणित को NCERT की मंशा के अनुसार पढ़ाते हैं — पहले अवधारणा, फिर शॉर्टकट। CTET, UPTET एवं सुपर TET बैचों का 12 वर्ष का अनुभव।"}'::jsonb, array['math']::text[], 12, array['hi']::text[]),
  ('edu-priya', 'Priya Sharma', '👩‍🎓', '{"en":"EVS & Science Pedagogy — 7 years","hi":"EVS एवं विज्ञान शिक्षाशास्त्र — 7 वर्ष"}'::jsonb, '{"en":"Ex-KV teacher. Her EVS classes work backwards from the NCERT chapter to the exact question CBSE has asked six times.","hi":"पूर्व KV शिक्षिका। उनकी EVS कक्षाएँ NCERT अध्याय से आरंभ होकर ठीक उसी प्रश्न तक पहुँचती हैं जो CBSE छह बार पूछ चुका है।"}'::jsonb, array['evs', 'science']::text[], 7, array['hi', 'en']::text[]),
  ('edu-imran', 'Imran Khan', '🧑‍🏫', '{"en":"English Language & Pedagogy — 10 years","hi":"अंग्रेज़ी भाषा एवं शिक्षाशास्त्र — 10 वर्ष"}'::jsonb, '{"en":"Trains Hindi-medium aspirants to score 27+ in Language II without memorising a single grammar rule out of context.","hi":"हिंदी माध्यम के अभ्यर्थियों को बिना संदर्भहीन व्याकरण रटे भाषा II में 27+ अंक लाने का प्रशिक्षण देते हैं।"}'::jsonb, array['english']::text[], 10, array['en', 'hi']::text[]),
  ('edu-sunita', 'Sunita Rathore', '👩‍💼', '{"en":"Hindi Vyakaran & Pedagogy — 14 years","hi":"हिंदी व्याकरण एवं शिक्षाशास्त्र — 14 वर्ष"}'::jsonb, '{"en":"The most-followed Hindi educator for REET and UPTET. Alankar and Ras in her classes are pattern recognition, not memorisation.","hi":"REET एवं UPTET हेतु सर्वाधिक फॉलो की जाने वाली हिंदी शिक्षिका। उनकी कक्षाओं में अलंकार एवं रस रटने के बजाय पैटर्न पहचान बन जाते हैं।"}'::jsonb, array['hindi', 'sanskrit']::text[], 14, array['hi']::text[]),
  ('edu-manoj', 'Manoj Tiwari', '👨‍💼', '{"en":"SST & State GK — 11 years","hi":"सामाजिक अध्ययन एवं राज्य GK — 11 वर्ष"}'::jsonb, '{"en":"Covers Haryana, UP, Bihar and Rajasthan state GK separately, because a national syllabus never gets you the state cut-off.","hi":"हरियाणा, UP, बिहार एवं राजस्थान राज्य GK अलग-अलग पढ़ाते हैं, क्योंकि राष्ट्रीय पाठ्यक्रम से राज्य का कट-ऑफ कभी पार नहीं होता।"}'::jsonb, array['sst', 'gk']::text[], 11, array['hi', 'en']::text[]),
  ('edu-neha', 'Neha Bansal', '👩‍🔬', '{"en":"Reasoning & Computer Literacy — 6 years","hi":"तर्कशक्ति एवं कंप्यूटर साक्षरता — 6 वर्ष"}'::jsonb, '{"en":"Specialises in the DSSSB and KVS general sections — the 70 marks most aspirants leave on the table.","hi":"DSSSB एवं KVS के सामान्य खंडों में विशेषज्ञ — वही 70 अंक जिन्हें अधिकांश अभ्यर्थी छोड़ देते हैं।"}'::jsonb, array['reasoning', 'computer']::text[], 6, array['en', 'hi']::text[])
insert into questions (id, subject_id, topic_id, exam_ids, text, options, correct_index, explanation, difficulty, previous_year, avg_time_seconds, accuracy, fingerprint) values
  ('q-cdp-001', 'cdp', 'cdp-piaget', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"According to Piaget, a child between 7 and 11 years of age is in which stage of cognitive development?","hi":"पियाजे के अनुसार 7 से 11 वर्ष आयु का बालक संज्ञानात्मक विकास की किस अवस्था में होता है?"}'::jsonb, '[{"en":"Sensorimotor stage","hi":"संवेदी-पेशीय अवस्था"},{"en":"Pre-operational stage","hi":"पूर्व-संक्रियात्मक अवस्था"},{"en":"Concrete operational stage","hi":"मूर्त संक्रियात्मक अवस्था"},{"en":"Formal operational stage","hi":"औपचारिक संक्रियात्मक अवस्था"}]'::jsonb, 2, '{"en":"Piaget places 7-11 years in the concrete operational stage. The child can now reason logically about concrete objects, and masters conservation, seriation and classification — but abstract hypothetical thinking arrives only in the formal operational stage (11+).","hi":"पियाजे 7-11 वर्ष को मूर्त संक्रियात्मक अवस्था में रखते हैं। इस अवस्था में बालक मूर्त वस्तुओं पर तार्किक चिंतन कर लेता है तथा संरक्षण, क्रमबद्धता एवं वर्गीकरण सीख जाता है — किंतु अमूर्त एवं परिकल्पनात्मक चिंतन औपचारिक संक्रियात्मक अवस्था (11+) में ही आता है।"}'::jsonb, 'easy', 'CTET Dec 2022 Paper 1', 32, 0.78, 'according to piaget a child between 7 and 11 years of age is in which stage of cognitive developmentपियाजे के अनुसार 7 से 11 वर्ष आयु का बालक संज्ञानात्मक विकास की किस अवस्था में होता है'),
  ('q-cdp-002', 'cdp', 'cdp-piaget', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The concept of the \"Zone of Proximal Development\" was given by:","hi":"\"निकटस्थ विकास का क्षेत्र\" (ZPD) की संकल्पना किसने दी?"}'::jsonb, '[{"en":"Jean Piaget","hi":"जीन पियाजे"},{"en":"Lev Vygotsky","hi":"लेव वाइगोत्स्की"},{"en":"Jerome Bruner","hi":"जेरोम ब्रूनर"},{"en":"Erik Erikson","hi":"एरिक एरिक्सन"}]'::jsonb, 1, '{"en":"Vygotsky defined the ZPD as the gap between what a learner can do alone and what they can do with guidance from a more knowledgeable other. Scaffolding — the term Bruner later coined — is the support given inside this zone.","hi":"वाइगोत्स्की ने ZPD को उस अंतर के रूप में परिभाषित किया जो बालक स्वयं कर सकता है तथा जो वह किसी अधिक जानकार व्यक्ति के मार्गदर्शन में कर सकता है, उनके बीच होता है। स्कैफोल्डिंग — यह शब्द बाद में ब्रूनर ने दिया — इसी क्षेत्र में दिया गया सहारा है।"}'::jsonb, 'easy', 'CTET Jan 2024 Paper 2', 25, 0.84, 'the concept of the zone of proximal development was given byनिकटस्थ विकास का क्षेत्र zpd की संकल्पना किसने दी'),
  ('q-cdp-003', 'cdp', 'cdp-growth', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Development proceeds from the head towards the feet. This principle is known as:","hi":"विकास सिर से पैरों की ओर होता है। यह सिद्धांत कहलाता है:"}'::jsonb, '[{"en":"Proximodistal principle","hi":"निकट-दूर का सिद्धांत"},{"en":"Cephalocaudal principle","hi":"मस्तकाधोमुखी सिद्धांत"},{"en":"Principle of continuity","hi":"निरंतरता का सिद्धांत"},{"en":"Principle of individual differences","hi":"वैयक्तिक भिन्नता का सिद्धांत"}]'::jsonb, 1, '{"en":"Cephalocaudal (\"head to tail\") development explains why an infant gains head control before sitting and sits before walking. The proximodistal principle is the complementary one: development moves from the centre of the body outwards to the limbs.","hi":"मस्तकाधोमुखी (\"सिर से पूँछ की ओर\") विकास बताता है कि शिशु बैठने से पहले सिर पर नियंत्रण तथा चलने से पहले बैठना क्यों सीखता है। निकट-दूर सिद्धांत इसका पूरक है: विकास शरीर के केंद्र से बाहर की ओर अंगों तक बढ़ता है।"}'::jsonb, 'easy', null, 28, 0.81, 'development proceeds from the head towards the feet this principle is known asविकास सिर से पैरों की ओर होता है यह सिद्धांत कहलाता है'),
  ('q-cdp-004', 'cdp', 'cdp-rte', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The Right to Education Act, 2009 provides free and compulsory education to children of which age group?","hi":"शिक्षा का अधिकार अधिनियम, 2009 किस आयु वर्ग के बालकों को निःशुल्क एवं अनिवार्य शिक्षा प्रदान करता है?"}'::jsonb, '[{"en":"3 to 12 years","hi":"3 से 12 वर्ष"},{"en":"6 to 14 years","hi":"6 से 14 वर्ष"},{"en":"6 to 18 years","hi":"6 से 18 वर्ष"},{"en":"5 to 15 years","hi":"5 से 15 वर्ष"}]'::jsonb, 1, '{"en":"Article 21-A and the RTE Act, 2009 guarantee free and compulsory education from 6 to 14 years — that is, elementary education, Classes 1 to 8. The Act came into force on 1 April 2010.","hi":"अनुच्छेद 21-क तथा RTE अधिनियम, 2009 के अंतर्गत 6 से 14 वर्ष तक निःशुल्क एवं अनिवार्य शिक्षा की गारंटी है — अर्थात् प्रारंभिक शिक्षा, कक्षा 1 से 8 तक। यह अधिनियम 1 अप्रैल 2010 से लागू हुआ।"}'::jsonb, 'easy', 'UPTET 2021 Paper 1', 22, 0.89, 'the right to education act 2009 provides free and compulsory education to children of which age groupशिक्षा का अधिकार अधिनियम 2009 किस आयु वर्ग के बालकों को निःशुल्क एवं अनिवार्य शिक्षा प्रदान करता है'),
  ('q-cdp-005', 'cdp', 'cdp-assessment', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Assessment which is carried out during the teaching-learning process to improve learning is called:","hi":"अधिगम को बेहतर बनाने हेतु शिक्षण-अधिगम प्रक्रिया के दौरान किया जाने वाला आकलन कहलाता है:"}'::jsonb, '[{"en":"Summative assessment","hi":"योगात्मक आकलन"},{"en":"Formative assessment","hi":"रचनात्मक आकलन"},{"en":"Diagnostic assessment","hi":"निदानात्मक आकलन"},{"en":"Norm-referenced assessment","hi":"मानक-संदर्भित आकलन"}]'::jsonb, 1, '{"en":"Formative assessment — assessment FOR learning — runs alongside teaching and feeds back into it. Summative assessment (assessment OF learning) happens at the end of a unit or term and mainly certifies achievement.","hi":"रचनात्मक आकलन — अधिगम के लिए आकलन — शिक्षण के साथ-साथ चलता है और उसी में फीडबैक देता है। योगात्मक आकलन (अधिगम का आकलन) इकाई या सत्र के अंत में होता है और मुख्यतः उपलब्धि प्रमाणित करता है।"}'::jsonb, 'medium', 'CTET Jul 2023 Paper 1', 35, 0.71, 'assessment which is carried out during the teaching learning process to improve learning is calledअधिगम को बेहतर बनाने हेतु शिक्षण अधिगम प्रक्रिया के दौरान किया जाने वाला आकलन कहलाता है'),
  ('q-cdp-006', 'cdp', 'cdp-intelligence', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The theory of Multiple Intelligences was propounded by:","hi":"बहु-बुद्धि सिद्धांत का प्रतिपादन किसने किया?"}'::jsonb, '[{"en":"Charles Spearman","hi":"चार्ल्स स्पीयरमैन"},{"en":"Howard Gardner","hi":"हावर्ड गार्डनर"},{"en":"Robert Sternberg","hi":"रॉबर्ट स्टर्नबर्ग"},{"en":"L. L. Thurstone","hi":"एल. एल. थर्स्टन"}]'::jsonb, 1, '{"en":"Howard Gardner (1983) argued intelligence is not one general factor but several relatively independent intelligences — linguistic, logical-mathematical, spatial, musical, bodily-kinaesthetic, interpersonal, intrapersonal and naturalistic. Sternberg gave the Triarchic theory; Spearman gave the two-factor (g and s) theory.","hi":"हावर्ड गार्डनर (1983) ने तर्क दिया कि बुद्धि एक सामान्य कारक नहीं बल्कि कई अपेक्षाकृत स्वतंत्र बुद्धियाँ हैं — भाषिक, तार्किक-गणितीय, स्थानिक, संगीतात्मक, शारीरिक-गतिक, अंतर्वैयक्तिक, अंतःवैयक्तिक तथा प्रकृतिवादी। स्टर्नबर्ग ने त्रितंत्र सिद्धांत तथा स्पीयरमैन ने द्विकारक (g एवं s) सिद्धांत दिया।"}'::jsonb, 'easy', 'REET 2022 Level 2', 26, 0.83, 'the theory of multiple intelligences was propounded byबहु बुद्धि सिद्धांत का प्रतिपादन किसने किया'),
  ('q-cdp-007', 'cdp', 'cdp-inclusive', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"A child in your class consistently reverses letters like b/d and reads very slowly despite normal intelligence. This is most likely:","hi":"आपकी कक्षा का एक बालक सामान्य बुद्धि होने के बावजूद b/d जैसे अक्षरों को उलट देता है तथा बहुत धीमा पढ़ता है। यह सर्वाधिक संभावित रूप से है:"}'::jsonb, '[{"en":"Dyscalculia","hi":"डिस्कैल्कुलिया"},{"en":"Dysgraphia","hi":"डिस्ग्राफिया"},{"en":"Dyslexia","hi":"डिस्लेक्सिया"},{"en":"Dyspraxia","hi":"डिस्प्रैक्सिया"}]'::jsonb, 2, '{"en":"Dyslexia is a specific learning disability in reading — letter reversal, slow decoding and poor spelling with intelligence intact. Dyscalculia affects number work, dysgraphia affects writing, and dyspraxia affects motor coordination. The teacher''s response should be remediation and accommodation, never labelling the child as lazy.","hi":"डिस्लेक्सिया पठन से संबंधित विशिष्ट अधिगम अक्षमता है — अक्षरों का उलटाव, धीमा डिकोडिंग तथा कमजोर वर्तनी, जबकि बुद्धि सामान्य रहती है। डिस्कैल्कुलिया गणित को, डिस्ग्राफिया लेखन को तथा डिस्प्रैक्सिया गत्यात्मक समन्वय को प्रभावित करता है। शिक्षक की प्रतिक्रिया उपचारात्मक शिक्षण एवं सुविधा होनी चाहिए, बालक को आलसी कहना नहीं।"}'::jsonb, 'medium', 'CTET Dec 2021 Paper 2', 38, 0.74, 'a child in your class consistently reverses letters like b d and reads very slowly despite normal intelligence this is most likelyआपकी कक्षा का एक बालक सामान्य बुद्धि होने के बावजूद b d जैसे अक्षरों को उलट देता है तथा बहुत धीमा पढ़ता है यह सर्वाधिक संभावित रूप से है'),
  ('q-cdp-008', 'cdp', 'cdp-learning', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Operant conditioning, based on reinforcement of voluntary behaviour, was given by:","hi":"ऐच्छिक व्यवहार के पुनर्बलन पर आधारित क्रिया-प्रसूत अनुबंधन किसने दिया?"}'::jsonb, '[{"en":"Ivan Pavlov","hi":"इवान पावलव"},{"en":"B. F. Skinner","hi":"बी. एफ. स्किनर"},{"en":"E. L. Thorndike","hi":"ई. एल. थार्नडाइक"},{"en":"Wolfgang Kohler","hi":"वोल्फगैंग कोहलर"}]'::jsonb, 1, '{"en":"Skinner''s operant conditioning works on consequences: behaviour followed by reinforcement is repeated. Pavlov gave classical conditioning (involuntary responses), Thorndike gave trial-and-error learning, and Kohler gave learning by insight.","hi":"स्किनर का क्रिया-प्रसूत अनुबंधन परिणामों पर आधारित है: जिस व्यवहार के बाद पुनर्बलन मिलता है, वह दोहराया जाता है। पावलव ने शास्त्रीय अनुबंधन (अनैच्छिक अनुक्रियाएँ), थार्नडाइक ने प्रयास एवं त्रुटि अधिगम तथा कोहलर ने अंतर्दृष्टि द्वारा अधिगम दिया।"}'::jsonb, 'easy', null, 24, 0.86, 'operant conditioning based on reinforcement of voluntary behaviour was given byऐच्छिक व्यवहार के पुनर्बलन पर आधारित क्रिया प्रसूत अनुबंधन किसने दिया'),
  ('q-cdp-009', 'cdp', 'cdp-learning', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Learning by insight was demonstrated through experiments on chimpanzees by:","hi":"चिंपैंजी पर किए गए प्रयोगों द्वारा अंतर्दृष्टि द्वारा अधिगम को किसने प्रदर्शित किया?"}'::jsonb, '[{"en":"Wolfgang Kohler","hi":"वोल्फगैंग कोहलर"},{"en":"Kurt Lewin","hi":"कर्ट लेविन"},{"en":"Albert Bandura","hi":"अल्बर्ट बंडूरा"},{"en":"Jerome Bruner","hi":"जेरोम ब्रूनर"}]'::jsonb, 0, '{"en":"Kohler''s Gestalt experiments with the chimpanzee Sultan showed sudden restructuring of the problem field — the \"aha\" moment — rather than gradual trial and error. Bandura is associated with social/observational learning.","hi":"कोहलर के गेस्टाल्ट प्रयोगों में चिंपैंजी सुल्तान ने समस्या-क्षेत्र का अचानक पुनर्गठन दिखाया — \"अहा\" क्षण — न कि क्रमिक प्रयास एवं त्रुटि। बंडूरा सामाजिक/प्रेक्षणात्मक अधिगम से संबंधित हैं।"}'::jsonb, 'medium', null, 30, 0.72, 'learning by insight was demonstrated through experiments on chimpanzees byचिंपैंजी पर किए गए प्रयोगों द्वारा अंतर्दृष्टि द्वारा अधिगम को किसने प्रदर्शित किया'),
  ('q-cdp-010', 'cdp', 'cdp-rte', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"NCF 2005 is primarily built on which view of learning?","hi":"NCF 2005 मुख्यतः अधिगम की किस दृष्टि पर आधारित है?"}'::jsonb, '[{"en":"Behaviourist — learning as habit formation","hi":"व्यवहारवादी — अधिगम आदत निर्माण के रूप में"},{"en":"Constructivist — learners construct knowledge","hi":"रचनावादी — शिक्षार्थी ज्ञान का निर्माण करते हैं"},{"en":"Transmission — teacher transfers knowledge","hi":"संचरणवादी — शिक्षक ज्ञान हस्तांतरित करता है"},{"en":"Maturationist — wait for readiness","hi":"परिपक्वतावादी — तत्परता की प्रतीक्षा"}]'::jsonb, 1, '{"en":"NCF 2005 rests on constructivism: knowledge is constructed by the learner from experience, so the classroom must connect learning to life outside school, move away from rote methods and treat the textbook as one resource among many.","hi":"NCF 2005 रचनावाद पर आधारित है: ज्ञान का निर्माण शिक्षार्थी अपने अनुभव से करता है, अतः कक्षा को विद्यालय के बाहर के जीवन से जोड़ना चाहिए, रटंत विधियों से दूर जाना चाहिए तथा पाठ्यपुस्तक को अनेक संसाधनों में से एक मानना चाहिए।"}'::jsonb, 'medium', 'CTET Jan 2024 Paper 1', 40, 0.68, 'ncf 2005 is primarily built on which view of learningncf 2005 मुख्यतः अधिगम की किस दृष्टि पर आधारित है'),
  ('q-cdp-011', 'cdp', 'cdp-motivation', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"A student studies because she genuinely enjoys understanding the subject. This is an example of:","hi":"एक छात्रा इसलिए पढ़ती है क्योंकि उसे विषय समझने में वास्तविक आनंद आता है। यह उदाहरण है:"}'::jsonb, '[{"en":"Extrinsic motivation","hi":"बाह्य अभिप्रेरणा"},{"en":"Intrinsic motivation","hi":"आंतरिक अभिप्रेरणा"},{"en":"Negative reinforcement","hi":"नकारात्मक पुनर्बलन"},{"en":"Achievement anxiety","hi":"उपलब्धि चिंता"}]'::jsonb, 1, '{"en":"Intrinsic motivation comes from within — curiosity, interest, the satisfaction of mastery. Extrinsic motivation depends on external rewards such as marks, prizes or praise, and research shows over-reliance on it can weaken intrinsic interest.","hi":"आंतरिक अभिप्रेरणा भीतर से आती है — जिज्ञासा, रुचि, निपुणता का संतोष। बाह्य अभिप्रेरणा अंक, पुरस्कार या प्रशंसा जैसे बाहरी प्रोत्साहनों पर निर्भर है, तथा शोध बताते हैं कि इस पर अत्यधिक निर्भरता आंतरिक रुचि को कमजोर कर सकती है।"}'::jsonb, 'easy', null, 23, 0.88, 'a student studies because she genuinely enjoys understanding the subject this is an example ofएक छात्रा इसलिए पढ़ती है क्योंकि उसे विषय समझने में वास्तविक आनंद आता है यह उदाहरण है'),
  ('q-cdp-012', 'cdp', 'cdp-gender', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Which of the following is the primary agency of socialisation for a young child?","hi":"निम्नलिखित में से कौन छोटे बालक के समाजीकरण की प्राथमिक अभिकरण है?"}'::jsonb, '[{"en":"School","hi":"विद्यालय"},{"en":"Peer group","hi":"सहपाठी समूह"},{"en":"Family","hi":"परिवार"},{"en":"Mass media","hi":"जनसंचार माध्यम"}]'::jsonb, 2, '{"en":"The family is the primary agency — first, most intimate and most sustained. School, peer group and media are secondary agencies whose influence grows as the child moves outward from home.","hi":"परिवार प्राथमिक अभिकरण है — सर्वप्रथम, सर्वाधिक निकट एवं सर्वाधिक निरंतर। विद्यालय, सहपाठी समूह एवं मीडिया द्वितीयक अभिकरण हैं जिनका प्रभाव बालक के घर से बाहर बढ़ने के साथ बढ़ता है।"}'::jsonb, 'easy', null, 20, 0.9, 'which of the following is the primary agency of socialisation for a young childनिम्नलिखित में से कौन छोटे बालक के समाजीकरण की प्राथमिक अभिकरण है'),
  ('q-cdp-013', 'cdp', 'cdp-intelligence', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"If a child''s mental age is 12 years and chronological age is 10 years, the IQ is:","hi":"यदि किसी बालक की मानसिक आयु 12 वर्ष तथा वास्तविक आयु 10 वर्ष है, तो बुद्धि लब्धि (IQ) होगी:"}'::jsonb, '[{"en":"83","hi":"83"},{"en":"100","hi":"100"},{"en":"120","hi":"120"},{"en":"144","hi":"144"}]'::jsonb, 2, '{"en":"IQ = (Mental Age ÷ Chronological Age) × 100 = (12 ÷ 10) × 100 = 120. The formula is Stern''s ratio IQ, popularised by Terman in the Stanford-Binet scale.","hi":"IQ = (मानसिक आयु ÷ वास्तविक आयु) × 100 = (12 ÷ 10) × 100 = 120। यह सूत्र स्टर्न का अनुपात IQ है, जिसे टर्मन ने स्टैनफोर्ड-बिने मापनी में प्रचलित किया।"}'::jsonb, 'easy', 'HTET 2021 Level 1', 33, 0.8, 'if a child s mental age is 12 years and chronological age is 10 years the iq isयदि किसी बालक की मानसिक आयु 12 वर्ष तथा वास्तविक आयु 10 वर्ष है तो बुद्धि लब्धि iq होगी'),
  ('q-cdp-014', 'cdp', 'cdp-learning', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"A teacher gives a challenging project and steps back, offering help only when the group gets stuck. This teaching strategy is best described as:","hi":"एक शिक्षक चुनौतीपूर्ण परियोजना देकर पीछे हट जाता है तथा समूह के अटकने पर ही सहायता देता है। यह शिक्षण रणनीति सर्वोत्तम रूप से कहलाती है:"}'::jsonb, '[{"en":"Rote drilling","hi":"रटंत अभ्यास"},{"en":"Scaffolding","hi":"स्कैफोल्डिंग (पाड़ लगाना)"},{"en":"Lecturing","hi":"व्याख्यान विधि"},{"en":"Streaming by ability","hi":"योग्यता के आधार पर वर्गीकरण"}]'::jsonb, 1, '{"en":"Scaffolding is temporary, responsive support inside the Zone of Proximal Development, withdrawn as competence grows. It is exactly what this teacher is doing — the support is contingent on need, not given upfront.","hi":"स्कैफोल्डिंग निकटस्थ विकास क्षेत्र में दिया गया अस्थायी एवं आवश्यकतानुसार सहारा है, जो योग्यता बढ़ने पर हटा लिया जाता है। यह शिक्षक ठीक यही कर रहा है — सहायता आवश्यकता पर आधारित है, पहले से दी गई नहीं।"}'::jsonb, 'medium', null, 42, 0.7, 'a teacher gives a challenging project and steps back offering help only when the group gets stuck this teaching strategy is best described asएक शिक्षक चुनौतीपूर्ण परियोजना देकर पीछे हट जाता है तथा समूह के अटकने पर ही सहायता देता है यह शिक्षण रणनीति सर्वोत्तम रूप से कहलाती है'),
  ('q-cdp-015', 'cdp', 'cdp-assessment', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Errors made by children in the classroom should be viewed by a teacher as:","hi":"कक्षा में बालकों द्वारा की गई त्रुटियों को शिक्षक द्वारा किस रूप में देखा जाना चाहिए?"}'::jsonb, '[{"en":"Proof of carelessness to be punished","hi":"लापरवाही का प्रमाण जिसे दंडित किया जाए"},{"en":"A window into the child''s thinking","hi":"बालक की सोच में झाँकने की खिड़की"},{"en":"A reason to lower expectations","hi":"अपेक्षाएँ घटाने का कारण"},{"en":"Something to be ignored entirely","hi":"पूर्णतः अनदेखा करने योग्य बात"}]'::jsonb, 1, '{"en":"Constructivist pedagogy treats errors as data. An error reveals the rule the child is actually using, which is what the teacher must address. This idea underlies error analysis in maths and language pedagogy questions alike.","hi":"रचनावादी शिक्षाशास्त्र त्रुटियों को आँकड़ा मानता है। त्रुटि उस नियम को उजागर करती है जिसे बालक वास्तव में प्रयोग कर रहा है, और शिक्षक को उसी पर कार्य करना है। यही विचार गणित तथा भाषा शिक्षाशास्त्र दोनों के त्रुटि विश्लेषण का आधार है।"}'::jsonb, 'easy', 'CTET Jul 2023 Paper 2', 30, 0.85, 'errors made by children in the classroom should be viewed by a teacher asकक्षा में बालकों द्वारा की गई त्रुटियों को शिक्षक द्वारा किस रूप में देखा जाना चाहिए'),
  ('q-math-001', 'math', 'math-number', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"What is the smallest prime number?","hi":"सबसे छोटी अभाज्य संख्या कौन-सी है?"}'::jsonb, '[{"en":"0","hi":"0"},{"en":"1","hi":"1"},{"en":"2","hi":"2"},{"en":"3","hi":"3"}]'::jsonb, 2, '{"en":"2 is the smallest prime and the only even prime. 1 is not prime because a prime must have exactly two distinct factors — 1 has only one.","hi":"2 सबसे छोटी अभाज्य संख्या तथा एकमात्र सम अभाज्य संख्या है। 1 अभाज्य नहीं है क्योंकि अभाज्य संख्या के ठीक दो भिन्न गुणनखंड होने चाहिए — 1 का केवल एक है।"}'::jsonb, 'easy', null, 15, 0.92, 'what is the smallest prime numberसबसे छोटी अभाज्य संख्या कौन सी है'),
  ('q-math-002', 'math', 'math-number', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The LCM of 12, 15 and 20 is:","hi":"12, 15 तथा 20 का लघुत्तम समापवर्त्य (LCM) है:"}'::jsonb, '[{"en":"30","hi":"30"},{"en":"60","hi":"60"},{"en":"120","hi":"120"},{"en":"180","hi":"180"}]'::jsonb, 1, '{"en":"12 = 2²×3, 15 = 3×5, 20 = 2²×5. Take the highest power of each prime: 2²×3×5 = 60. Check: 60 is divisible by 12, 15 and 20.","hi":"12 = 2²×3, 15 = 3×5, 20 = 2²×5। प्रत्येक अभाज्य की उच्चतम घात लें: 2²×3×5 = 60। जाँच: 60, 12, 15 तथा 20 तीनों से विभाज्य है।"}'::jsonb, 'easy', 'CTET Dec 2022 Paper 1', 45, 0.79, 'the lcm of 12 15 and 20 is12 15 तथा 20 का लघुत्तम समापवर्त्य lcm है'),
  ('q-math-003', 'math', 'math-number', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The value of 3/4 + 5/6 is:","hi":"3/4 + 5/6 का मान है:"}'::jsonb, '[{"en":"8/10","hi":"8/10"},{"en":"19/12","hi":"19/12"},{"en":"15/24","hi":"15/24"},{"en":"4/5","hi":"4/5"}]'::jsonb, 1, '{"en":"LCM of 4 and 6 is 12. So 3/4 = 9/12 and 5/6 = 10/12. Adding: 9/12 + 10/12 = 19/12 (or 1 7/12).","hi":"4 तथा 6 का LCM 12 है। अतः 3/4 = 9/12 तथा 5/6 = 10/12। जोड़ने पर: 9/12 + 10/12 = 19/12 (अथवा 1 7/12)।"}'::jsonb, 'easy', null, 50, 0.76, 'the value of 3 4 5 6 is3 4 5 6 का मान है'),
  ('q-math-004', 'math', 'math-mensuration', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The area of a rectangle is 96 sq cm and its length is 12 cm. Its perimeter is:","hi":"एक आयत का क्षेत्रफल 96 वर्ग सेमी तथा लंबाई 12 सेमी है। इसका परिमाप है:"}'::jsonb, '[{"en":"40 cm","hi":"40 सेमी"},{"en":"44 cm","hi":"44 सेमी"},{"en":"48 cm","hi":"48 सेमी"},{"en":"56 cm","hi":"56 सेमी"}]'::jsonb, 0, '{"en":"Breadth = Area ÷ Length = 96 ÷ 12 = 8 cm. Perimeter = 2(l + b) = 2(12 + 8) = 2 × 20 = 40 cm.","hi":"चौड़ाई = क्षेत्रफल ÷ लंबाई = 96 ÷ 12 = 8 सेमी। परिमाप = 2(ल + चौ) = 2(12 + 8) = 2 × 20 = 40 सेमी।"}'::jsonb, 'medium', 'REET 2022 Level 1', 55, 0.73, 'the area of a rectangle is 96 sq cm and its length is 12 cm its perimeter isएक आयत का क्षेत्रफल 96 वर्ग सेमी तथा लंबाई 12 सेमी है इसका परिमाप है'),
  ('q-math-005', 'math', 'math-arith', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"A shopkeeper buys an item for ₹800 and sells it for ₹920. His profit percentage is:","hi":"एक दुकानदार ₹800 में वस्तु खरीदकर ₹920 में बेचता है। उसका लाभ प्रतिशत है:"}'::jsonb, '[{"en":"12%","hi":"12%"},{"en":"15%","hi":"15%"},{"en":"18%","hi":"18%"},{"en":"20%","hi":"20%"}]'::jsonb, 1, '{"en":"Profit = 920 − 800 = ₹120. Profit % = (Profit ÷ Cost Price) × 100 = (120 ÷ 800) × 100 = 15%.","hi":"लाभ = 920 − 800 = ₹120। लाभ % = (लाभ ÷ क्रय मूल्य) × 100 = (120 ÷ 800) × 100 = 15%।"}'::jsonb, 'easy', null, 48, 0.81, 'a shopkeeper buys an item for 800 and sells it for 920 his profit percentage isएक दुकानदार 800 में वस्तु खरीदकर 920 में बेचता है उसका लाभ प्रतिशत है'),
  ('q-math-006', 'math', 'math-number', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"In the number 5,74,832, the place value of 4 is:","hi":"संख्या 5,74,832 में 4 का स्थानीय मान है:"}'::jsonb, '[{"en":"4","hi":"4"},{"en":"400","hi":"400"},{"en":"4,000","hi":"4,000"},{"en":"40,000","hi":"40,000"}]'::jsonb, 2, '{"en":"Reading 5,74,832 from the right: 2 (ones), 3 (tens), 8 (hundreds), 4 (thousands), 7 (ten thousands), 5 (lakhs). So 4 sits in the thousands place — place value 4,000. Its face value remains 4.","hi":"5,74,832 को दाएँ से पढ़ें: 2 (इकाई), 3 (दहाई), 8 (सैकड़ा), 4 (हजार), 7 (दस हजार), 5 (लाख)। अतः 4 हजार के स्थान पर है — स्थानीय मान 4,000। इसका अंकित मान 4 ही रहेगा।"}'::jsonb, 'easy', null, 38, 0.84, 'in the number 5 74 832 the place value of 4 isसंख्या 5 74 832 में 4 का स्थानीय मान है'),
  ('q-math-007', 'math', 'math-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"According to the Van Hiele model, the first level of learning geometry is:","hi":"वान हील मॉडल के अनुसार ज्यामिति अधिगम का प्रथम स्तर है:"}'::jsonb, '[{"en":"Visualisation","hi":"दृश्यीकरण"},{"en":"Analysis","hi":"विश्लेषण"},{"en":"Informal deduction","hi":"अनौपचारिक निगमन"},{"en":"Formal deduction","hi":"औपचारिक निगमन"}]'::jsonb, 0, '{"en":"Van Hiele levels run: visualisation (recognising shapes by appearance) → analysis (noticing properties) → informal deduction (relating properties) → formal deduction (proof) → rigour. A primary child works mostly at level 0-1, which is why geometry must start with handling and seeing shapes, not definitions.","hi":"वान हील स्तर हैं: दृश्यीकरण (आकृति को देखकर पहचानना) → विश्लेषण (गुणों को पहचानना) → अनौपचारिक निगमन (गुणों को जोड़ना) → औपचारिक निगमन (उपपत्ति) → कठोरता। प्राथमिक स्तर का बालक प्रायः स्तर 0-1 पर होता है, इसीलिए ज्यामिति परिभाषाओं से नहीं, आकृतियों को देखने-छूने से आरंभ होनी चाहिए।"}'::jsonb, 'hard', 'CTET Jan 2024 Paper 1', 55, 0.52, 'according to the van hiele model the first level of learning geometry isवान हील मॉडल के अनुसार ज्यामिति अधिगम का प्रथम स्तर है'),
  ('q-math-008', 'math', 'math-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"A child writes 25 + 17 = 312 by adding digits column-wise without carrying. The teacher should:","hi":"एक बालक हासिल लिए बिना स्तंभवार अंक जोड़कर 25 + 17 = 312 लिखता है। शिक्षक को चाहिए:"}'::jsonb, '[{"en":"Mark it wrong and move on","hi":"गलत अंकित कर आगे बढ़ जाना"},{"en":"Make the child rewrite the sum ten times","hi":"बालक से यह जोड़ दस बार लिखवाना"},{"en":"Use bundles of ten sticks to rebuild the idea of carrying","hi":"हासिल की अवधारणा को दस-दस की गड्डियों से पुनः बनाना"},{"en":"Tell the child maths is not their strength","hi":"बालक से कहना कि गणित उसका विषय नहीं है"}]'::jsonb, 2, '{"en":"The error is conceptual, not careless — the child has not internalised place value and regrouping. Concrete material (bundles of ten, base-ten blocks) rebuilds the idea. Repetition without understanding, or discouragement, addresses neither the cause nor the child.","hi":"त्रुटि वैचारिक है, लापरवाही नहीं — बालक ने स्थानीय मान एवं पुनर्समूहन को आत्मसात नहीं किया। मूर्त सामग्री (दस-दस की गड्डियाँ, बेस-टेन ब्लॉक) अवधारणा को पुनः बनाती है। बिना समझ की पुनरावृत्ति अथवा हतोत्साहन न कारण का समाधान करते हैं न बालक का।"}'::jsonb, 'medium', null, 45, 0.87, 'a child writes 25 17 312 by adding digits column wise without carrying the teacher shouldएक बालक हासिल लिए बिना स्तंभवार अंक जोड़कर 25 17 312 लिखता है शिक्षक को चाहिए'),
  ('q-math-009', 'math', 'math-geometry', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"How many lines of symmetry does an equilateral triangle have?","hi":"एक समबाहु त्रिभुज में सममित रेखाओं की संख्या कितनी होती है?"}'::jsonb, '[{"en":"1","hi":"1"},{"en":"2","hi":"2"},{"en":"3","hi":"3"},{"en":"Infinite","hi":"अनंत"}]'::jsonb, 2, '{"en":"An equilateral triangle has 3 lines of symmetry — one from each vertex to the midpoint of the opposite side. A square has 4, a circle has infinitely many, and a scalene triangle has none.","hi":"समबाहु त्रिभुज में 3 सममित रेखाएँ होती हैं — प्रत्येक शीर्ष से सम्मुख भुजा के मध्य बिंदु तक एक। वर्ग में 4, वृत्त में अनंत तथा विषमबाहु त्रिभुज में एक भी नहीं होती।"}'::jsonb, 'easy', null, 30, 0.82, 'how many lines of symmetry does an equilateral triangle haveएक समबाहु त्रिभुज में सममित रेखाओं की संख्या कितनी होती है'),
  ('q-math-010', 'math', 'math-arith', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"If 5 pens cost ₹75, how much will 13 pens cost?","hi":"यदि 5 पेन का मूल्य ₹75 है, तो 13 पेन का मूल्य कितना होगा?"}'::jsonb, '[{"en":"₹165","hi":"₹165"},{"en":"₹185","hi":"₹185"},{"en":"₹195","hi":"₹195"},{"en":"₹205","hi":"₹205"}]'::jsonb, 2, '{"en":"Unit price = 75 ÷ 5 = ₹15 per pen. For 13 pens: 15 × 13 = ₹195. This is the unitary method, a Class 5-6 staple.","hi":"एक पेन का मूल्य = 75 ÷ 5 = ₹15। 13 पेन हेतु: 15 × 13 = ₹195। यह ऐकिक नियम है, जो कक्षा 5-6 का मूल विषय है।"}'::jsonb, 'easy', null, 35, 0.88, 'if 5 pens cost 75 how much will 13 pens costयदि 5 पेन का मूल्य 75 है तो 13 पेन का मूल्य कितना होगा'),
  ('q-evs-001', 'evs', 'evs-food', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Which of the following is the richest natural source of Vitamin C?","hi":"निम्नलिखित में से कौन विटामिन C का सर्वाधिक समृद्ध प्राकृतिक स्रोत है?"}'::jsonb, '[{"en":"Milk","hi":"दूध"},{"en":"Amla (Indian gooseberry)","hi":"आँवला"},{"en":"Rice","hi":"चावल"},{"en":"Groundnut","hi":"मूँगफली"}]'::jsonb, 1, '{"en":"Amla has among the highest Vitamin C content of any common Indian food. Deficiency of Vitamin C causes scurvy — bleeding gums and slow wound healing.","hi":"आँवले में किसी भी सामान्य भारतीय खाद्य पदार्थ की तुलना में सर्वाधिक विटामिन C होता है। विटामिन C की कमी से स्कर्वी होता है — मसूड़ों से रक्तस्राव तथा घाव का धीरे भरना।"}'::jsonb, 'easy', null, 20, 0.9, 'which of the following is the richest natural source of vitamin cनिम्नलिखित में से कौन विटामिन c का सर्वाधिक समृद्ध प्राकृतिक स्रोत है'),
  ('q-evs-002', 'evs', 'evs-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The primary aim of teaching EVS at the primary stage is to:","hi":"प्राथमिक स्तर पर EVS शिक्षण का मुख्य उद्देश्य है:"}'::jsonb, '[{"en":"Prepare children for Class 6 Science","hi":"बालकों को कक्षा 6 विज्ञान हेतु तैयार करना"},{"en":"Help children explore and connect with their immediate environment","hi":"बालकों को अपने निकट पर्यावरण से जोड़ना एवं उसकी खोज कराना"},{"en":"Complete the textbook within the session","hi":"सत्र में पाठ्यपुस्तक पूरी करना"},{"en":"Teach scientific terminology early","hi":"वैज्ञानिक शब्दावली शीघ्र सिखाना"}]'::jsonb, 1, '{"en":"EVS at the primary stage is an integrated subject built around the child''s own surroundings — family, food, water, shelter, travel. Exploration, observation and questioning matter more than terminology, which comes later.","hi":"प्राथमिक स्तर पर EVS एक एकीकृत विषय है जो बालक के अपने परिवेश — परिवार, भोजन, पानी, आवास, यात्रा — के इर्द-गिर्द बनता है। खोज, प्रेक्षण एवं प्रश्न पूछना शब्दावली से अधिक महत्वपूर्ण हैं, जो बाद में आती है।"}'::jsonb, 'medium', 'CTET Dec 2022 Paper 1', 40, 0.79, 'the primary aim of teaching evs at the primary stage is toप्राथमिक स्तर पर evs शिक्षण का मुख्य उद्देश्य है'),
  ('q-evs-003', 'evs', 'evs-water', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Stepwells locally called \"baoli\" or \"bawadi\" are traditional water structures mainly found in:","hi":"स्थानीय रूप से \"बावली\" अथवा \"बावड़ी\" कहलाने वाली सीढ़ीदार जल संरचनाएँ मुख्यतः कहाँ मिलती हैं?"}'::jsonb, '[{"en":"Kerala and Tamil Nadu","hi":"केरल तथा तमिलनाडु"},{"en":"Rajasthan and Gujarat","hi":"राजस्थान तथा गुजरात"},{"en":"Assam and Meghalaya","hi":"असम तथा मेघालय"},{"en":"Punjab and Himachal","hi":"पंजाब तथा हिमाचल"}]'::jsonb, 1, '{"en":"Baolis are a water-harvesting response to arid climates and are concentrated in Rajasthan and Gujarat — Rani ki Vav in Patan and Chand Baori in Abhaneri being the best known. The CTET EVS syllabus covers them under the \"Water\" theme.","hi":"बावड़ियाँ शुष्क जलवायु में जल संचयन की प्रतिक्रिया हैं तथा राजस्थान एवं गुजरात में केंद्रित हैं — पाटन की रानी की वाव तथा आभानेरी की चाँद बावड़ी सर्वाधिक प्रसिद्ध हैं। CTET EVS पाठ्यक्रम में ये \"पानी\" विषय के अंतर्गत आती हैं।"}'::jsonb, 'medium', 'CTET Jul 2023 Paper 1', 35, 0.66, 'stepwells locally called baoli or bawadi are traditional water structures mainly found inस्थानीय रूप से बावली अथवा बावड़ी कहलाने वाली सीढ़ीदार जल संरचनाएँ मुख्यतः कहाँ मिलती हैं'),
  ('q-evs-004', 'evs', 'evs-travel', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The famous \"toy train\" that is a UNESCO World Heritage Site runs in:","hi":"यूनेस्को विश्व धरोहर स्थल घोषित प्रसिद्ध \"टॉय ट्रेन\" कहाँ चलती है?"}'::jsonb, '[{"en":"Shimla and Darjeeling","hi":"शिमला तथा दार्जिलिंग"},{"en":"Ooty and Munnar","hi":"ऊटी तथा मुन्नार"},{"en":"Nainital and Mussoorie","hi":"नैनीताल तथा मसूरी"},{"en":"Gangtok and Shillong","hi":"गंगटोक तथा शिलांग"}]'::jsonb, 0, '{"en":"The Mountain Railways of India — the Darjeeling Himalayan Railway, the Kalka-Shimla Railway and the Nilgiri Mountain Railway — are UNESCO World Heritage Sites. Darjeeling and Shimla are the pair named in NCERT EVS.","hi":"भारत की पर्वतीय रेलवे — दार्जिलिंग हिमालयन रेलवे, कालका-शिमला रेलवे तथा नीलगिरि माउंटेन रेलवे — यूनेस्को विश्व धरोहर स्थल हैं। NCERT EVS में दार्जिलिंग तथा शिमला का उल्लेख है।"}'::jsonb, 'easy', null, 28, 0.75, 'the famous toy train that is a unesco world heritage site runs inयूनेस्को विश्व धरोहर स्थल घोषित प्रसिद्ध टॉय ट्रेन कहाँ चलती है'),
  ('q-evs-005', 'evs', 'evs-family', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"In a family, your mother''s brother''s daughter is your:","hi":"परिवार में आपकी माता के भाई की पुत्री आपकी क्या लगेगी?"}'::jsonb, '[{"en":"Sister","hi":"बहन"},{"en":"Cousin","hi":"चचेरी/ममेरी बहन"},{"en":"Aunt","hi":"मौसी"},{"en":"Niece","hi":"भांजी"}]'::jsonb, 1, '{"en":"Mother''s brother is the maternal uncle (mama); his daughter is your cousin — in Hindi kinship, mameri behen. Relationship questions of this type appear in both EVS and reasoning sections.","hi":"माता का भाई मामा होता है; उसकी पुत्री आपकी ममेरी बहन अर्थात् कज़िन हुई। इस प्रकार के संबंध-प्रश्न EVS तथा तर्कशक्ति दोनों खंडों में आते हैं।"}'::jsonb, 'easy', null, 25, 0.83, 'in a family your mother s brother s daughter is yourपरिवार में आपकी माता के भाई की पुत्री आपकी क्या लगेगी'),
  ('q-evs-006', 'evs', 'evs-food', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Which animal is known as the \"ship of the desert\"?","hi":"किस पशु को \"रेगिस्तान का जहाज\" कहा जाता है?"}'::jsonb, '[{"en":"Horse","hi":"घोड़ा"},{"en":"Camel","hi":"ऊँट"},{"en":"Donkey","hi":"गधा"},{"en":"Yak","hi":"याक"}]'::jsonb, 1, '{"en":"The camel stores fat in its hump, tolerates large water loss and has broad padded feet for sand — adaptations that make it the desert''s transport animal. The yak plays the same role in cold high altitudes.","hi":"ऊँट अपने कूबड़ में वसा संचित करता है, अधिक जल हानि सह लेता है तथा उसके चौड़े गद्दीदार पैर रेत के लिए उपयुक्त होते हैं — यही अनुकूलन उसे मरुस्थल का वाहन बनाते हैं। ठंडे उच्च पर्वतीय क्षेत्रों में याक यही भूमिका निभाता है।"}'::jsonb, 'easy', null, 15, 0.95, 'which animal is known as the ship of the desertकिस पशु को रेगिस्तान का जहाज कहा जाता है'),
  ('q-evs-007', 'evs', 'evs-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The most appropriate way to assess EVS learning at the primary stage is:","hi":"प्राथमिक स्तर पर EVS अधिगम के आकलन का सर्वाधिक उपयुक्त तरीका है:"}'::jsonb, '[{"en":"A written test of definitions","hi":"परिभाषाओं की लिखित परीक्षा"},{"en":"Observation of children during activities, surveys and discussions","hi":"गतिविधियों, सर्वेक्षणों एवं चर्चाओं के दौरान बालकों का प्रेक्षण"},{"en":"Ranking children by marks","hi":"अंकों के आधार पर बालकों की श्रेणी बनाना"},{"en":"Counting how many chapters were finished","hi":"कितने अध्याय पूरे हुए, इसकी गणना"}]'::jsonb, 1, '{"en":"EVS is assessed continuously and comprehensively through observation, projects, surveys, group work and portfolios. Written tests of definitions test recall, not the exploration and reasoning EVS is meant to develop.","hi":"EVS का आकलन प्रेक्षण, परियोजना, सर्वेक्षण, समूह कार्य एवं पोर्टफोलियो द्वारा सतत एवं व्यापक रूप से होता है। परिभाषाओं की लिखित परीक्षा केवल स्मरण जाँचती है, वह खोज एवं तर्क नहीं जिसे EVS विकसित करना चाहता है।"}'::jsonb, 'medium', null, 38, 0.82, 'the most appropriate way to assess evs learning at the primary stage isप्राथमिक स्तर पर evs अधिगम के आकलन का सर्वाधिक उपयुक्त तरीका है'),
  ('q-evs-008', 'evs', 'evs-shelter', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Houses on stilts are commonly built in regions that face:","hi":"खंभों पर बने घर सामान्यतः किन क्षेत्रों में बनाए जाते हैं?"}'::jsonb, '[{"en":"Frequent flooding or heavy rainfall","hi":"बार-बार बाढ़ अथवा भारी वर्षा वाले"},{"en":"Extreme cold","hi":"अत्यधिक ठंड वाले"},{"en":"Desert heat","hi":"मरुस्थलीय गर्मी वाले"},{"en":"Frequent earthquakes only","hi":"केवल भूकंप-प्रवण"}]'::jsonb, 0, '{"en":"Stilt houses keep the living floor above flood water and damp ground, which is why they appear in Assam, coastal Kerala and the north-east. Shelter in EVS is always taught as a response to local climate and material.","hi":"खंभों पर बने घर रहने की मंजिल को बाढ़ के पानी तथा नम भूमि से ऊपर रखते हैं, इसीलिए ये असम, तटीय केरल तथा पूर्वोत्तर में मिलते हैं। EVS में आवास सदैव स्थानीय जलवायु एवं सामग्री की प्रतिक्रिया के रूप में पढ़ाया जाता है।"}'::jsonb, 'easy', null, 30, 0.86, 'houses on stilts are commonly built in regions that faceखंभों पर बने घर सामान्यतः किन क्षेत्रों में बनाए जाते हैं'),
  ('q-hin-001', 'hindi', 'hindi-vyakaran', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"Identify the correct sandhi-viched of \"विद्यालय\".","hi":"\"विद्यालय\" का सही संधि-विच्छेद पहचानिए।"}'::jsonb, '[{"en":"विद्या + लय","hi":"विद्या + लय"},{"en":"विद्य + आलय","hi":"विद्य + आलय"},{"en":"विद्या + आलय","hi":"विद्या + आलय"},{"en":"विद् + यालय","hi":"विद् + यालय"}]'::jsonb, 2, '{"en":"विद्या + आलय = विद्यालय. Two similar vowels (आ + आ) combine into a long आ — this is दीर्घ संधि, a sub-type of स्वर संधि.","hi":"विद्या + आलय = विद्यालय। दो सजातीय स्वर (आ + आ) मिलकर दीर्घ आ बनाते हैं — यह दीर्घ संधि है, जो स्वर संधि का उपभेद है।"}'::jsonb, 'easy', 'UPTET 2021 Paper 1', 30, 0.8, 'identify the correct sandhi viched of विद्यालयविद्यालय का सही संधि विच्छेद पहचानिए'),
  ('q-hin-002', 'hindi', 'hindi-alankar', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"In the line \"चारु चंद्र की चंचल किरणें\", which alankar is used?","hi":"\"चारु चंद्र की चंचल किरणें\" पंक्ति में कौन-सा अलंकार है?"}'::jsonb, '[{"en":"उपमा अलंकार","hi":"उपमा अलंकार"},{"en":"अनुप्रास अलंकार","hi":"अनुप्रास अलंकार"},{"en":"रूपक अलंकार","hi":"रूपक अलंकार"},{"en":"यमक अलंकार","hi":"यमक अलंकार"}]'::jsonb, 1, '{"en":"The repeated \"च\" sound at the start of चारु, चंद्र and चंचल is अनुप्रास (alliteration). उपमा compares two things with a connecting word, रूपक identifies them, and यमक repeats a word with different meanings.","hi":"चारु, चंद्र तथा चंचल के आरंभ में \"च\" वर्ण की आवृत्ति अनुप्रास अलंकार है। उपमा में उपमेय-उपमान की तुलना वाचक शब्द से होती है, रूपक में अभेद आरोप होता है तथा यमक में एक शब्द भिन्न अर्थों में दोहराया जाता है।"}'::jsonb, 'medium', null, 35, 0.71, 'in the line चारु चंद्र की चंचल किरणें which alankar is usedचारु चंद्र की चंचल किरणें पंक्ति में कौन सा अलंकार है'),
  ('q-hin-003', 'hindi', 'hindi-shabd', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The tatsam form of the tadbhav word \"आग\" is:","hi":"\"आग\" (तद्भव) शब्द का तत्सम रूप है:"}'::jsonb, '[{"en":"अनल","hi":"अनल"},{"en":"अग्नि","hi":"अग्नि"},{"en":"ज्वाला","hi":"ज्वाला"},{"en":"पावक","hi":"पावक"}]'::jsonb, 1, '{"en":"आग derives directly from Sanskrit अग्नि, so अग्नि is its tatsam form. अनल and पावक are synonyms of fire, not the source word of आग.","hi":"आग शब्द सीधे संस्कृत अग्नि से विकसित हुआ है, अतः अग्नि इसका तत्सम रूप है। अनल तथा पावक अग्नि के पर्यायवाची हैं, आग के मूल शब्द नहीं।"}'::jsonb, 'easy', null, 25, 0.84, 'the tatsam form of the tadbhav word आग isआग तद्भव शब्द का तत्सम रूप है'),
  ('q-hin-004', 'hindi', 'hindi-vyakaran', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"The muhavara \"नौ दो ग्यारह होना\" means:","hi":"मुहावरे \"नौ दो ग्यारह होना\" का अर्थ है:"}'::jsonb, '[{"en":"बहुत धन कमाना","hi":"बहुत धन कमाना"},{"en":"भाग जाना","hi":"भाग जाना"},{"en":"गिनती करना","hi":"गिनती करना"},{"en":"झगड़ा करना","hi":"झगड़ा करना"}]'::jsonb, 1, '{"en":"\"नौ दो ग्यारह होना\" means to run away or flee. Idioms carry figurative, not literal, meaning — a point often tested in pedagogy questions too.","hi":"\"नौ दो ग्यारह होना\" का अर्थ है भाग जाना। मुहावरे लाक्षणिक अर्थ देते हैं, शाब्दिक नहीं — यही बात शिक्षाशास्त्र के प्रश्नों में भी पूछी जाती है।"}'::jsonb, 'easy', null, 20, 0.89, 'the muhavara नौ दो ग्यारह होना meansमुहावरे नौ दो ग्यारह होना का अर्थ है'),
  ('q-hin-005', 'hindi', 'hindi-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"According to language pedagogy, the most effective way to develop a child''s vocabulary is:","hi":"भाषा शिक्षाशास्त्र के अनुसार बालक की शब्द-संपदा विकसित करने का सर्वाधिक प्रभावी तरीका है:"}'::jsonb, '[{"en":"शब्दार्थ रटवाना","hi":"शब्दार्थ रटवाना"},{"en":"सार्थक संदर्भ में भाषा का प्रयोग कराना","hi":"सार्थक संदर्भ में भाषा का प्रयोग कराना"},{"en":"प्रतिदिन श्रुतलेख कराना","hi":"प्रतिदिन श्रुतलेख कराना"},{"en":"शब्दकोश याद कराना","hi":"शब्दकोश याद कराना"}]'::jsonb, 1, '{"en":"Vocabulary grows through meaningful use — reading, listening, conversation and writing in real contexts. Isolated word lists produce recognition without usage, which is why NCF places language learning inside communication.","hi":"शब्द-संपदा सार्थक प्रयोग से बढ़ती है — वास्तविक संदर्भों में पढ़ना, सुनना, बातचीत तथा लेखन। पृथक शब्द-सूचियाँ केवल पहचान देती हैं, प्रयोग नहीं, इसीलिए NCF भाषा अधिगम को संप्रेषण के भीतर रखता है।"}'::jsonb, 'medium', 'CTET Dec 2022 Paper 1', 40, 0.83, 'according to language pedagogy the most effective way to develop a child s vocabulary isभाषा शिक्षाशास्त्र के अनुसार बालक की शब्द संपदा विकसित करने का सर्वाधिक प्रभावी तरीका है'),
  ('q-hin-006', 'hindi', 'hindi-vyakaran', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet']::text[], '{"en":"How many vowels (स्वर) are there in the Hindi Devanagari alphabet as conventionally taught?","hi":"हिंदी देवनागरी वर्णमाला में परंपरागत रूप से कितने स्वर माने जाते हैं?"}'::jsonb, '[{"en":"10","hi":"10"},{"en":"11","hi":"11"},{"en":"13","hi":"13"},{"en":"16","hi":"16"}]'::jsonb, 1, '{"en":"Conventionally 11 vowels are counted: अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ. Adding अं and अः (which are अयोगवाह, not true vowels) gives the figure 13 that some books quote.","hi":"परंपरागत रूप से 11 स्वर गिने जाते हैं: अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ। अं तथा अः (जो अयोगवाह हैं, वास्तविक स्वर नहीं) जोड़ने पर कुछ पुस्तकों में दी गई संख्या 13 बनती है।"}'::jsonb, 'medium', null, 28, 0.64, 'how many vowels स्वर are there in the hindi devanagari alphabet as conventionally taughtहिंदी देवनागरी वर्णमाला में परंपरागत रूप से कितने स्वर माने जाते हैं'),
  ('q-eng-001', 'english', 'eng-grammar', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Choose the correct sentence:","hi":"सही वाक्य चुनिए:"}'::jsonb, '[{"en":"She has been teaching since five years.","hi":"She has been teaching since five years."},{"en":"She has been teaching for five years.","hi":"She has been teaching for five years."},{"en":"She is teaching since five years.","hi":"She is teaching since five years."},{"en":"She teaches since five years.","hi":"She teaches since five years."}]'::jsonb, 1, '{"en":"\"For\" is used with a period of time (five years); \"since\" is used with a point in time (2019, Monday). The present perfect continuous — has been teaching — is required for an action starting in the past and still going on.","hi":"\"For\" का प्रयोग समय-अवधि (five years) के साथ तथा \"since\" का प्रयोग समय-बिंदु (2019, Monday) के साथ होता है। भूतकाल में आरंभ होकर अब तक जारी क्रिया हेतु present perfect continuous — has been teaching — आवश्यक है।"}'::jsonb, 'easy', null, 30, 0.79, 'choose the correct sentenceसही वाक्य चुनिए'),
  ('q-eng-002', 'english', 'eng-vocab', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Choose the word most nearly opposite in meaning to \"ABUNDANT\":","hi":"\"ABUNDANT\" के लगभग विपरीतार्थक शब्द का चयन कीजिए:"}'::jsonb, '[{"en":"Plentiful","hi":"Plentiful"},{"en":"Scarce","hi":"Scarce"},{"en":"Ample","hi":"Ample"},{"en":"Copious","hi":"Copious"}]'::jsonb, 1, '{"en":"Abundant means existing in large quantity. Scarce — insufficient, hard to find — is its antonym. Plentiful, ample and copious are all synonyms of abundant.","hi":"Abundant का अर्थ है प्रचुर मात्रा में विद्यमान। Scarce — अपर्याप्त, दुर्लभ — इसका विलोम है। Plentiful, ample तथा copious तीनों abundant के पर्यायवाची हैं।"}'::jsonb, 'easy', null, 22, 0.85, 'choose the word most nearly opposite in meaning to abundantabundant के लगभग विपरीतार्थक शब्द का चयन कीजिए'),
  ('q-eng-003', 'english', 'eng-grammar', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Identify the part of speech of the underlined word: \"She sings *beautifully*.\"","hi":"रेखांकित शब्द का पदभेद पहचानिए: \"She sings *beautifully*.\""}'::jsonb, '[{"en":"Adjective","hi":"विशेषण (Adjective)"},{"en":"Adverb","hi":"क्रियाविशेषण (Adverb)"},{"en":"Noun","hi":"संज्ञा (Noun)"},{"en":"Preposition","hi":"संबंधसूचक (Preposition)"}]'::jsonb, 1, '{"en":"\"Beautifully\" modifies the verb \"sings\" — telling us how she sings — so it is an adverb of manner. \"Beautiful\" would be the adjective form, modifying a noun.","hi":"\"Beautifully\" क्रिया \"sings\" को संशोधित करता है — यह बताता है कि वह कैसे गाती है — अतः यह रीतिवाचक क्रियाविशेषण है। \"Beautiful\" विशेषण रूप होगा, जो संज्ञा को संशोधित करता है।"}'::jsonb, 'easy', null, 25, 0.87, 'identify the part of speech of the underlined word she sings beautifullyरेखांकित शब्द का पदभेद पहचानिए she sings beautifully'),
  ('q-eng-004', 'english', 'eng-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The best approach to teach grammar to young learners is:","hi":"छोटे शिक्षार्थियों को व्याकरण पढ़ाने का सर्वोत्तम उपागम है:"}'::jsonb, '[{"en":"Deductive — state the rule, then drill it","hi":"निगमनात्मक — नियम बताकर अभ्यास कराना"},{"en":"Inductive — let learners notice patterns in meaningful language","hi":"आगमनात्मक — शिक्षार्थियों को सार्थक भाषा में पैटर्न पहचानने देना"},{"en":"Translation of every rule into the mother tongue","hi":"प्रत्येक नियम का मातृभाषा में अनुवाद"},{"en":"Memorising grammar tables weekly","hi":"साप्ताहिक व्याकरण तालिकाएँ याद कराना"}]'::jsonb, 1, '{"en":"Communicative language teaching favours the inductive route: learners meet language in use, notice the pattern, and the rule is formalised afterwards. Rules stated first and drilled out of context produce knowledge about the language rather than the ability to use it.","hi":"संप्रेषणात्मक भाषा शिक्षण आगमनात्मक मार्ग को प्राथमिकता देता है: शिक्षार्थी भाषा को प्रयोग में देखते हैं, पैटर्न पहचानते हैं तथा नियम बाद में औपचारिक होता है। पहले नियम बताकर संदर्भहीन अभ्यास कराने से भाषा के \"बारे में\" ज्ञान बनता है, भाषा प्रयोग की क्षमता नहीं।"}'::jsonb, 'medium', 'CTET Jan 2024 Paper 2', 42, 0.76, 'the best approach to teach grammar to young learners isछोटे शिक्षार्थियों को व्याकरण पढ़ाने का सर्वोत्तम उपागम है'),
  ('q-eng-005', 'english', 'eng-grammar', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Fill in the blank: \"If I ___ the answer, I would tell you.\"","hi":"रिक्त स्थान भरिए: \"If I ___ the answer, I would tell you.\""}'::jsonb, '[{"en":"know","hi":"know"},{"en":"knew","hi":"knew"},{"en":"have known","hi":"have known"},{"en":"will know","hi":"will know"}]'::jsonb, 1, '{"en":"This is a second conditional — an unreal present situation. The pattern is: If + past simple, would + base verb. Hence \"If I knew the answer, I would tell you.\"","hi":"यह second conditional है — वर्तमान की काल्पनिक स्थिति। संरचना है: If + past simple, would + मूल क्रिया। अतः \"If I knew the answer, I would tell you.\""}'::jsonb, 'medium', null, 30, 0.72, 'fill in the blank if i the answer i would tell youरिक्त स्थान भरिए if i the answer i would tell you'),
  ('q-eng-006', 'english', 'eng-phonetics', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The sounds /p/, /b/, /m/ are produced at which place of articulation?","hi":"/p/, /b/, /m/ ध्वनियाँ किस उच्चारण स्थान से उत्पन्न होती हैं?"}'::jsonb, '[{"en":"Bilabial","hi":"द्वयोष्ठ्य (Bilabial)"},{"en":"Dental","hi":"दंत्य (Dental)"},{"en":"Velar","hi":"कंठ्य (Velar)"},{"en":"Glottal","hi":"स्वरयंत्रीय (Glottal)"}]'::jsonb, 0, '{"en":"/p/, /b/ and /m/ are made by bringing both lips together — bilabial sounds. /t/, /d/ are alveolar/dental; /k/, /g/ are velar; /h/ is glottal.","hi":"/p/, /b/ तथा /m/ दोनों ओष्ठों को मिलाकर बनती हैं — द्वयोष्ठ्य ध्वनियाँ। /t/, /d/ वर्त्स्य/दंत्य; /k/, /g/ कंठ्य तथा /h/ स्वरयंत्रीय है।"}'::jsonb, 'hard', null, 38, 0.55, 'the sounds p b m are produced at which place of articulationp b m ध्वनियाँ किस उच्चारण स्थान से उत्पन्न होती हैं'),
  ('q-sci-001', 'science', 'sci-living', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Which part of the plant carries out photosynthesis?","hi":"पौधे का कौन-सा भाग प्रकाश संश्लेषण करता है?"}'::jsonb, '[{"en":"Root","hi":"जड़"},{"en":"Stem","hi":"तना"},{"en":"Leaf","hi":"पत्ती"},{"en":"Flower","hi":"फूल"}]'::jsonb, 2, '{"en":"Leaves contain chloroplasts with chlorophyll, and stomata for gas exchange, making them the primary site of photosynthesis: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ in the presence of sunlight.","hi":"पत्तियों में क्लोरोफिल युक्त हरितलवक तथा गैस विनिमय हेतु रंध्र होते हैं, अतः वे प्रकाश संश्लेषण का मुख्य स्थल हैं: सूर्य प्रकाश की उपस्थिति में 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂।"}'::jsonb, 'easy', null, 18, 0.93, 'which part of the plant carries out photosynthesisपौधे का कौन सा भाग प्रकाश संश्लेषण करता है'),
  ('q-sci-002', 'science', 'sci-motion', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The SI unit of force is:","hi":"बल का SI मात्रक है:"}'::jsonb, '[{"en":"Joule","hi":"जूल"},{"en":"Newton","hi":"न्यूटन"},{"en":"Watt","hi":"वाट"},{"en":"Pascal","hi":"पास्कल"}]'::jsonb, 1, '{"en":"Force is measured in newtons (N), where 1 N = 1 kg·m/s². Joule is energy, watt is power and pascal is pressure.","hi":"बल का मात्रक न्यूटन (N) है, जहाँ 1 N = 1 किग्रा·मी/से²। जूल ऊर्जा का, वाट शक्ति का तथा पास्कल दाब का मात्रक है।"}'::jsonb, 'easy', null, 20, 0.9, 'the si unit of force isबल का si मात्रक है'),
  ('q-sci-003', 'science', 'sci-matter', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Which of the following is a chemical change?","hi":"निम्नलिखित में से कौन रासायनिक परिवर्तन है?"}'::jsonb, '[{"en":"Melting of ice","hi":"बर्फ का पिघलना"},{"en":"Rusting of iron","hi":"लोहे में जंग लगना"},{"en":"Dissolving sugar in water","hi":"चीनी का पानी में घुलना"},{"en":"Breaking of glass","hi":"काँच का टूटना"}]'::jsonb, 1, '{"en":"Rusting forms a new substance — hydrated iron oxide — and is irreversible, so it is a chemical change. Melting, dissolving and breaking alter only physical state or form; the substance stays the same.","hi":"जंग लगने पर नया पदार्थ — जलयोजित आयरन ऑक्साइड — बनता है तथा यह अनुत्क्रमणीय है, अतः यह रासायनिक परिवर्तन है। पिघलना, घुलना एवं टूटना केवल भौतिक अवस्था या रूप बदलते हैं; पदार्थ वही रहता है।"}'::jsonb, 'easy', 'CTET Dec 2021 Paper 2', 28, 0.87, 'which of the following is a chemical changeनिम्नलिखित में से कौन रासायनिक परिवर्तन है'),
  ('q-sci-004', 'science', 'sci-food-health', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Deficiency of which vitamin causes night blindness?","hi":"किस विटामिन की कमी से रतौंधी होती है?"}'::jsonb, '[{"en":"Vitamin A","hi":"विटामिन A"},{"en":"Vitamin B12","hi":"विटामिन B12"},{"en":"Vitamin C","hi":"विटामिन C"},{"en":"Vitamin D","hi":"विटामिन D"}]'::jsonb, 0, '{"en":"Vitamin A (retinol) is needed for rhodopsin in the retina; deficiency causes night blindness and, if severe, xerophthalmia. Carrots, papaya and green leafy vegetables are good sources.","hi":"विटामिन A (रेटिनॉल) रेटिना में रोडोप्सिन हेतु आवश्यक है; इसकी कमी से रतौंधी तथा गंभीर स्थिति में जीरोफ्थैल्मिया होता है। गाजर, पपीता तथा हरी पत्तेदार सब्जियाँ अच्छे स्रोत हैं।"}'::jsonb, 'easy', null, 18, 0.91, 'deficiency of which vitamin causes night blindnessकिस विटामिन की कमी से रतौंधी होती है'),
  ('q-sci-005', 'science', 'sci-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The best way to teach the concept of \"evaporation\" to Class 6 students is:","hi":"कक्षा 6 के विद्यार्थियों को \"वाष्पीकरण\" की अवधारणा पढ़ाने का सर्वोत्तम तरीका है:"}'::jsonb, '[{"en":"Dictating the definition and making them memorise it","hi":"परिभाषा लिखवाकर याद कराना"},{"en":"Letting them observe wet cloth drying and design a simple experiment","hi":"गीले कपड़े को सूखते देखने देना तथा सरल प्रयोग रचवाना"},{"en":"Showing only the textbook diagram","hi":"केवल पाठ्यपुस्तक का चित्र दिखाना"},{"en":"Asking them to write the definition ten times","hi":"परिभाषा दस बार लिखवाना"}]'::jsonb, 1, '{"en":"Science pedagogy at the upper primary stage is inquiry-based: observe a familiar phenomenon, ask a question, predict, test and explain. Definitions come after the experience, not instead of it.","hi":"उच्च प्राथमिक स्तर पर विज्ञान शिक्षाशास्त्र अन्वेषण आधारित है: परिचित घटना का प्रेक्षण, प्रश्न, पूर्वानुमान, परीक्षण तथा व्याख्या। परिभाषाएँ अनुभव के बाद आती हैं, उसके स्थान पर नहीं।"}'::jsonb, 'medium', null, 38, 0.88, 'the best way to teach the concept of evaporation to class 6 students isकक्षा 6 के विद्यार्थियों को वाष्पीकरण की अवधारणा पढ़ाने का सर्वोत्तम तरीका है'),
  ('q-sci-006', 'science', 'sci-natural', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Which gas is most responsible for the greenhouse effect being intensified by human activity?","hi":"मानवीय गतिविधियों द्वारा ग्रीनहाउस प्रभाव को तीव्र करने हेतु सर्वाधिक उत्तरदायी गैस कौन-सी है?"}'::jsonb, '[{"en":"Oxygen","hi":"ऑक्सीजन"},{"en":"Nitrogen","hi":"नाइट्रोजन"},{"en":"Carbon dioxide","hi":"कार्बन डाइऑक्साइड"},{"en":"Helium","hi":"हीलियम"}]'::jsonb, 2, '{"en":"Carbon dioxide from burning fossil fuels is the largest human contribution to the enhanced greenhouse effect. Methane and nitrous oxide are stronger per molecule but far less abundant.","hi":"जीवाश्म ईंधन जलाने से निकली कार्बन डाइऑक्साइड बढ़े हुए ग्रीनहाउस प्रभाव में मानव का सबसे बड़ा योगदान है। मीथेन तथा नाइट्रस ऑक्साइड प्रति अणु अधिक प्रभावी हैं किंतु मात्रा में बहुत कम।"}'::jsonb, 'easy', null, 25, 0.89, 'which gas is most responsible for the greenhouse effect being intensified by human activityमानवीय गतिविधियों द्वारा ग्रीनहाउस प्रभाव को तीव्र करने हेतु सर्वाधिक उत्तरदायी गैस कौन सी है'),
  ('q-sst-001', 'sst', 'sst-civics', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The Fundamental Duties were added to the Indian Constitution by which amendment?","hi":"भारतीय संविधान में मूल कर्तव्य किस संशोधन द्वारा जोड़े गए?"}'::jsonb, '[{"en":"42nd Amendment, 1976","hi":"42वाँ संशोधन, 1976"},{"en":"44th Amendment, 1978","hi":"44वाँ संशोधन, 1978"},{"en":"73rd Amendment, 1992","hi":"73वाँ संशोधन, 1992"},{"en":"86th Amendment, 2002","hi":"86वाँ संशोधन, 2002"}]'::jsonb, 0, '{"en":"The 42nd Amendment (1976) inserted Part IVA, Article 51A, listing ten Fundamental Duties on the recommendation of the Swaran Singh Committee. An eleventh duty — providing education to children aged 6-14 — was added by the 86th Amendment (2002).","hi":"42वें संशोधन (1976) ने स्वर्ण सिंह समिति की संस्तुति पर भाग IVक, अनुच्छेद 51क जोड़कर दस मूल कर्तव्य सूचीबद्ध किए। ग्यारहवाँ कर्तव्य — 6-14 वर्ष के बालकों को शिक्षा देना — 86वें संशोधन (2002) द्वारा जोड़ा गया।"}'::jsonb, 'medium', 'DSSSB TGT 2023', 35, 0.68, 'the fundamental duties were added to the indian constitution by which amendmentभारतीय संविधान में मूल कर्तव्य किस संशोधन द्वारा जोड़े गए'),
  ('q-sst-002', 'sst', 'sst-history', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The Dandi March of 1930 was launched by Mahatma Gandhi against:","hi":"1930 का दांडी मार्च महात्मा गांधी ने किसके विरुद्ध आरंभ किया था?"}'::jsonb, '[{"en":"The Rowlatt Act","hi":"रौलेट अधिनियम"},{"en":"The salt tax","hi":"नमक कर"},{"en":"The partition of Bengal","hi":"बंगाल विभाजन"},{"en":"The Simon Commission","hi":"साइमन कमीशन"}]'::jsonb, 1, '{"en":"Gandhi walked 240 miles from Sabarmati to Dandi (12 March - 6 April 1930) and broke the salt law by making salt from seawater, launching the Civil Disobedience Movement.","hi":"गांधीजी ने साबरमती से दांडी तक 240 मील (12 मार्च - 6 अप्रैल 1930) पैदल यात्रा कर समुद्री जल से नमक बनाकर नमक कानून तोड़ा तथा सविनय अवज्ञा आंदोलन आरंभ किया।"}'::jsonb, 'easy', null, 25, 0.9, 'the dandi march of 1930 was launched by mahatma gandhi against1930 का दांडी मार्च महात्मा गांधी ने किसके विरुद्ध आरंभ किया था'),
  ('q-sst-003', 'sst', 'sst-geography', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The Tropic of Cancer passes through how many Indian states?","hi":"कर्क रेखा भारत के कितने राज्यों से होकर गुजरती है?"}'::jsonb, '[{"en":"6","hi":"6"},{"en":"7","hi":"7"},{"en":"8","hi":"8"},{"en":"9","hi":"9"}]'::jsonb, 2, '{"en":"The Tropic of Cancer (23°30′N) passes through 8 states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram.","hi":"कर्क रेखा (23°30′ उत्तर) 8 राज्यों से गुजरती है: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा तथा मिजोरम।"}'::jsonb, 'medium', null, 30, 0.7, 'the tropic of cancer passes through how many indian statesकर्क रेखा भारत के कितने राज्यों से होकर गुजरती है'),
  ('q-sst-004', 'sst', 'sst-civics', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Who is the constitutional head of the Indian State?","hi":"भारतीय राज्य का संवैधानिक प्रमुख कौन होता है?"}'::jsonb, '[{"en":"The Prime Minister","hi":"प्रधानमंत्री"},{"en":"The President","hi":"राष्ट्रपति"},{"en":"The Chief Justice of India","hi":"भारत के मुख्य न्यायाधीश"},{"en":"The Speaker of Lok Sabha","hi":"लोकसभा अध्यक्ष"}]'::jsonb, 1, '{"en":"The President is the constitutional (nominal) head of the Indian Union under Article 52-53, while real executive power rests with the Council of Ministers headed by the Prime Minister.","hi":"अनुच्छेद 52-53 के अंतर्गत राष्ट्रपति भारतीय संघ का संवैधानिक (नाममात्र) प्रमुख होता है, जबकि वास्तविक कार्यपालिका शक्ति प्रधानमंत्री की अध्यक्षता वाली मंत्रिपरिषद में निहित है।"}'::jsonb, 'easy', null, 20, 0.92, 'who is the constitutional head of the indian stateभारतीय राज्य का संवैधानिक प्रमुख कौन होता है'),
  ('q-sst-005', 'sst', 'sst-pedagogy', array['ctet', 'htet', 'uptet', 'bihartet', 'reet', 'mptet', 'wbtet', 'dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"The most appropriate way to teach \"local self-government\" in Class 7 is:","hi":"कक्षा 7 में \"स्थानीय स्वशासन\" पढ़ाने का सर्वाधिक उपयुक्त तरीका है:"}'::jsonb, '[{"en":"Dictating notes on the 73rd Amendment","hi":"73वें संशोधन पर नोट्स लिखवाना"},{"en":"Organising a mock gram sabha in the classroom","hi":"कक्षा में मॉक ग्राम सभा आयोजित करना"},{"en":"Asking children to memorise the panchayat structure","hi":"पंचायत संरचना रटवाना"},{"en":"Showing a single chart and moving on","hi":"एक चार्ट दिखाकर आगे बढ़ जाना"}]'::jsonb, 1, '{"en":"Social Studies pedagogy asks for participation and enquiry — role play, mock bodies, local field visits and interviews. A mock gram sabha turns an abstract structure into an experience the child can reason about.","hi":"सामाजिक अध्ययन शिक्षाशास्त्र सहभागिता एवं अन्वेषण चाहता है — भूमिका निर्वाह, मॉक निकाय, स्थानीय भ्रमण एवं साक्षात्कार। मॉक ग्राम सभा अमूर्त संरचना को ऐसे अनुभव में बदल देती है जिस पर बालक तर्क कर सके।"}'::jsonb, 'medium', null, 40, 0.85, 'the most appropriate way to teach local self government in class 7 isकक्षा 7 में स्थानीय स्वशासन पढ़ाने का सर्वाधिक उपयुक्त तरीका है'),
  ('q-gk-001', 'gk', 'gk-polity', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"National Education Policy (NEP) 2020 replaced the earlier policy of which year?","hi":"राष्ट्रीय शिक्षा नीति (NEP) 2020 ने किस वर्ष की पूर्ववर्ती नीति का स्थान लिया?"}'::jsonb, '[{"en":"1968","hi":"1968"},{"en":"1986 (modified 1992)","hi":"1986 (1992 में संशोधित)"},{"en":"2005","hi":"2005"},{"en":"2009","hi":"2009"}]'::jsonb, 1, '{"en":"NEP 2020 replaced the National Policy on Education 1986, as modified in 1992. It introduced the 5+3+3+4 curricular structure and set a target of 6% of GDP for education spending.","hi":"NEP 2020 ने 1986 की राष्ट्रीय शिक्षा नीति (1992 में संशोधित) का स्थान लिया। इसने 5+3+3+4 पाठ्यचर्या संरचना दी तथा शिक्षा व्यय हेतु GDP का 6% लक्ष्य निर्धारित किया।"}'::jsonb, 'easy', 'KVS PRT 2023', 25, 0.86, 'national education policy nep 2020 replaced the earlier policy of which yearराष्ट्रीय शिक्षा नीति nep 2020 ने किस वर्ष की पूर्ववर्ती नीति का स्थान लिया'),
  ('q-gk-002', 'gk', 'gk-state', array['htet', 'hssc-tgt-pgt']::text[], '{"en":"Which is the largest district of Haryana by area?","hi":"क्षेत्रफल की दृष्टि से हरियाणा का सबसे बड़ा जिला कौन-सा है?"}'::jsonb, '[{"en":"Hisar","hi":"हिसार"},{"en":"Sirsa","hi":"सिरसा"},{"en":"Bhiwani","hi":"भिवानी"},{"en":"Gurugram","hi":"गुरुग्राम"}]'::jsonb, 1, '{"en":"Sirsa is Haryana''s largest district by area (about 4,277 sq km). Bhiwani was the largest before Charkhi Dadri was carved out of it in 2016. Haryana GK carries 25% weight in HSSC papers.","hi":"क्षेत्रफल की दृष्टि से सिरसा हरियाणा का सबसे बड़ा जिला है (लगभग 4,277 वर्ग किमी)। 2016 में चरखी दादरी अलग होने से पूर्व भिवानी सबसे बड़ा था। HSSC पेपरों में हरियाणा GK का 25% भार होता है।"}'::jsonb, 'medium', null, 25, 0.62, 'which is the largest district of haryana by areaक्षेत्रफल की दृष्टि से हरियाणा का सबसे बड़ा जिला कौन सा है'),
  ('q-gk-003', 'gk', 'gk-static', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"National Education Day is observed in India on:","hi":"भारत में राष्ट्रीय शिक्षा दिवस कब मनाया जाता है?"}'::jsonb, '[{"en":"5 September","hi":"5 सितंबर"},{"en":"11 November","hi":"11 नवंबर"},{"en":"14 November","hi":"14 नवंबर"},{"en":"26 November","hi":"26 नवंबर"}]'::jsonb, 1, '{"en":"National Education Day is 11 November, the birth anniversary of Maulana Abul Kalam Azad, independent India''s first Education Minister. 5 September is Teachers'' Day (Dr Radhakrishnan''s birthday).","hi":"राष्ट्रीय शिक्षा दिवस 11 नवंबर को स्वतंत्र भारत के प्रथम शिक्षा मंत्री मौलाना अबुल कलाम आज़ाद की जयंती पर मनाया जाता है। 5 सितंबर शिक्षक दिवस (डॉ. राधाकृष्णन का जन्मदिन) है।"}'::jsonb, 'easy', null, 20, 0.81, 'national education day is observed in india onभारत में राष्ट्रीय शिक्षा दिवस कब मनाया जाता है'),
  ('q-gk-004', 'gk', 'gk-polity', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Education was moved from the State List to the Concurrent List by which amendment?","hi":"शिक्षा को राज्य सूची से समवर्ती सूची में किस संशोधन द्वारा स्थानांतरित किया गया?"}'::jsonb, '[{"en":"42nd Amendment, 1976","hi":"42वाँ संशोधन, 1976"},{"en":"44th Amendment, 1978","hi":"44वाँ संशोधन, 1978"},{"en":"52nd Amendment, 1985","hi":"52वाँ संशोधन, 1985"},{"en":"86th Amendment, 2002","hi":"86वाँ संशोधन, 2002"}]'::jsonb, 0, '{"en":"The 42nd Amendment (1976) shifted education to the Concurrent List, which is why both the Centre and the States now legislate on it. The 86th Amendment made elementary education a fundamental right.","hi":"42वें संशोधन (1976) ने शिक्षा को समवर्ती सूची में स्थानांतरित किया, इसीलिए अब केंद्र एवं राज्य दोनों इस पर विधि बना सकते हैं। 86वें संशोधन ने प्रारंभिक शिक्षा को मूल अधिकार बनाया।"}'::jsonb, 'medium', 'DSSSB PRT 2022', 30, 0.64, 'education was moved from the state list to the concurrent list by which amendmentशिक्षा को राज्य सूची से समवर्ती सूची में किस संशोधन द्वारा स्थानांतरित किया गया'),
  ('q-rea-001', 'reasoning', 'rea-series', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Find the next term: 3, 6, 11, 18, 27, ?","hi":"अगला पद ज्ञात कीजिए: 3, 6, 11, 18, 27, ?"}'::jsonb, '[{"en":"36","hi":"36"},{"en":"38","hi":"38"},{"en":"40","hi":"40"},{"en":"42","hi":"42"}]'::jsonb, 1, '{"en":"Differences are 3, 5, 7, 9 — consecutive odd numbers. The next difference is 11, so 27 + 11 = 38.","hi":"अंतर हैं 3, 5, 7, 9 — क्रमागत विषम संख्याएँ। अगला अंतर 11 होगा, अतः 27 + 11 = 38।"}'::jsonb, 'medium', null, 45, 0.74, 'find the next term 3 6 11 18 27अगला पद ज्ञात कीजिए 3 6 11 18 27'),
  ('q-rea-002', 'reasoning', 'rea-coding', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"If TEACHER is coded as UFBDIFS, then SCHOOL will be coded as:","hi":"यदि TEACHER को UFBDIFS लिखा जाए, तो SCHOOL को लिखा जाएगा:"}'::jsonb, '[{"en":"TDIPPM","hi":"TDIPPM"},{"en":"TDJPPM","hi":"TDJPPM"},{"en":"SDIPPM","hi":"SDIPPM"},{"en":"TDIPPN","hi":"TDIPPN"}]'::jsonb, 0, '{"en":"Each letter moves one step forward: T→U, E→F, A→B, C→D, H→I, E→F, R→S. Applying the same to SCHOOL: S→T, C→D, H→I, O→P, O→P, L→M = TDIPPM.","hi":"प्रत्येक अक्षर एक स्थान आगे बढ़ता है: T→U, E→F, A→B, C→D, H→I, E→F, R→S। यही नियम SCHOOL पर लगाने पर: S→T, C→D, H→I, O→P, O→P, L→M = TDIPPM।"}'::jsonb, 'easy', null, 40, 0.83, 'if teacher is coded as ufbdifs then school will be coded asयदि teacher को ufbdifs लिखा जाए तो school को लिखा जाएगा'),
  ('q-rea-003', 'reasoning', 'rea-blood', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Pointing to a photograph, Ravi said, \"She is the daughter of my grandfather''s only son.\" How is she related to Ravi?","hi":"एक तस्वीर की ओर संकेत करते हुए रवि ने कहा, \"यह मेरे दादा के इकलौते पुत्र की पुत्री है।\" वह रवि की क्या लगती है?"}'::jsonb, '[{"en":"Cousin","hi":"चचेरी बहन"},{"en":"Sister","hi":"बहन"},{"en":"Aunt","hi":"बुआ"},{"en":"Niece","hi":"भतीजी"}]'::jsonb, 1, '{"en":"Grandfather''s only son is Ravi''s own father. The father''s daughter is therefore Ravi''s sister.","hi":"दादा का इकलौता पुत्र स्वयं रवि के पिता हैं। अतः पिता की पुत्री रवि की बहन हुई।"}'::jsonb, 'easy', null, 35, 0.8, 'pointing to a photograph ravi said she is the daughter of my grandfather s only son how is she related to raviएक तस्वीर की ओर संकेत करते हुए रवि ने कहा यह मेरे दादा के इकलौते पुत्र की पुत्री है वह रवि की क्या लगती है'),
  ('q-rea-004', 'reasoning', 'rea-syllogism', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Statements: All teachers are graduates. Some graduates are researchers. Which conclusion follows?","hi":"कथन: सभी शिक्षक स्नातक हैं। कुछ स्नातक शोधकर्ता हैं। कौन-सा निष्कर्ष निकलता है?"}'::jsonb, '[{"en":"All teachers are researchers","hi":"सभी शिक्षक शोधकर्ता हैं"},{"en":"Some teachers are researchers","hi":"कुछ शिक्षक शोधकर्ता हैं"},{"en":"No teacher is a researcher","hi":"कोई शिक्षक शोधकर्ता नहीं है"},{"en":"Neither conclusion necessarily follows","hi":"कोई भी निष्कर्ष आवश्यक रूप से नहीं निकलता"}]'::jsonb, 3, '{"en":"The researchers among graduates may lie entirely outside the teacher subset, so neither \"some teachers are researchers\" nor \"no teacher is a researcher\" is guaranteed. In syllogism, a possibility is not a conclusion.","hi":"स्नातकों में जो शोधकर्ता हैं वे पूर्णतः शिक्षक उपसमुच्चय के बाहर हो सकते हैं, अतः न \"कुछ शिक्षक शोधकर्ता हैं\" और न ही \"कोई शिक्षक शोधकर्ता नहीं\" निश्चित है। न्यायवाक्य में संभावना निष्कर्ष नहीं होती।"}'::jsonb, 'hard', null, 55, 0.51, 'statements all teachers are graduates some graduates are researchers which conclusion followsकथन सभी शिक्षक स्नातक हैं कुछ स्नातक शोधकर्ता हैं कौन सा निष्कर्ष निकलता है'),
  ('q-comp-001', 'computer', 'comp-basics', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"Which of the following is an input device?","hi":"निम्नलिखित में से कौन एक निवेश (input) युक्ति है?"}'::jsonb, '[{"en":"Monitor","hi":"मॉनिटर"},{"en":"Printer","hi":"प्रिंटर"},{"en":"Scanner","hi":"स्कैनर"},{"en":"Speaker","hi":"स्पीकर"}]'::jsonb, 2, '{"en":"A scanner feeds data into the computer, making it an input device. Monitor, printer and speaker all deliver output from the computer to the user.","hi":"स्कैनर कंप्यूटर में डेटा भेजता है, अतः यह निवेश युक्ति है। मॉनिटर, प्रिंटर तथा स्पीकर तीनों कंप्यूटर से उपयोगकर्ता तक निर्गत (output) पहुँचाते हैं।"}'::jsonb, 'easy', null, 15, 0.94, 'which of the following is an input deviceनिम्नलिखित में से कौन एक निवेश input युक्ति है'),
  ('q-comp-002', 'computer', 'comp-ict', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"DIKSHA, launched by the Ministry of Education, is primarily a:","hi":"शिक्षा मंत्रालय द्वारा आरंभ दीक्षा (DIKSHA) मुख्यतः क्या है?"}'::jsonb, '[{"en":"Digital platform for school education content and teacher training","hi":"विद्यालयी शिक्षा सामग्री एवं शिक्षक प्रशिक्षण हेतु डिजिटल मंच"},{"en":"Student scholarship scheme","hi":"छात्र छात्रवृत्ति योजना"},{"en":"School building programme","hi":"विद्यालय भवन कार्यक्रम"},{"en":"Mid-day meal scheme","hi":"मध्याह्न भोजन योजना"}]'::jsonb, 0, '{"en":"DIKSHA (Digital Infrastructure for Knowledge Sharing) hosts e-content, QR-coded textbooks and teacher training modules such as NISHTHA. Questions on national ed-tech initiatives are common in KVS and NVS computer sections.","hi":"दीक्षा (Digital Infrastructure for Knowledge Sharing) पर ई-सामग्री, QR कोड युक्त पाठ्यपुस्तकें तथा निष्ठा जैसे शिक्षक प्रशिक्षण मॉड्यूल उपलब्ध हैं। राष्ट्रीय एड-टेक पहलों पर प्रश्न KVS तथा NVS के कंप्यूटर खंड में सामान्य हैं।"}'::jsonb, 'easy', null, 25, 0.84, 'diksha launched by the ministry of education is primarily aशिक्षा मंत्रालय द्वारा आरंभ दीक्षा diksha मुख्यतः क्या है'),
  ('q-comp-003', 'computer', 'comp-basics', array['dsssb', 'kvs', 'nvs', 'hssc-tgt-pgt', 'supertet', 'awes', 'emrs']::text[], '{"en":"1 Gigabyte (GB) is equal to:","hi":"1 गीगाबाइट (GB) बराबर होता है:"}'::jsonb, '[{"en":"1024 Kilobytes","hi":"1024 किलोबाइट"},{"en":"1024 Megabytes","hi":"1024 मेगाबाइट"},{"en":"1024 Terabytes","hi":"1024 टेराबाइट"},{"en":"1000 Bytes","hi":"1000 बाइट"}]'::jsonb, 1, '{"en":"The binary progression is: 1 KB = 1024 bytes, 1 MB = 1024 KB, 1 GB = 1024 MB, 1 TB = 1024 GB.","hi":"द्विआधारी क्रम है: 1 KB = 1024 बाइट, 1 MB = 1024 KB, 1 GB = 1024 MB, 1 TB = 1024 GB।"}'::jsonb, 'easy', null, 18, 0.9, '1 gigabyte gb is equal to1 गीगाबाइट gb बराबर होता है')
