values (gen_random_uuid(), 'Kavita M.', '🙋‍♀️', 'cdp', '{"en":"In conservation tasks, is it egocentrism or centration that stops a 5-year-old from answering correctly?","hi":"संरक्षण कार्यों में 5 वर्ष के बालक को सही उत्तर देने से अहंकेंद्रितता रोकती है या केंद्रीकरण?"}'::jsonb, '2026-08-12T09:20:00+05:30'::timestamptz, 148);
select id, 'Anjali Verma', true, '{"en":"Centration. The child focuses on one dimension — usually the height of the glass — and ignores width. Egocentrism is the inability to take another person''s viewpoint, tested by the three-mountain task, not the conservation task.","hi":"केंद्रीकरण। बालक एक ही आयाम पर ध्यान देता है — प्रायः गिलास की ऊँचाई — तथा चौड़ाई की उपेक्षा करता है। अहंकेंद्रितता दूसरे के दृष्टिकोण को न समझ पाना है, जिसकी जाँच त्रि-पर्वत कार्य से होती है, संरक्षण कार्य से नहीं।"}'::jsonb, '2026-08-12T10:05:00+05:30'::timestamptz, 213
